-- READINESS SWEEP, BATCH 4: process gaps. Approved GJM, effective 2026-10-29.
-- FRM-702 v3 can hold one of our own lots; FRM-701's batch check names the CCP records; FRM-913 checks allergen
-- segregation (11.6.3 guidance); FRM-207 takes 'Supplied by the customer' and SOP-2.3.4 says how; FRM-903
-- records single-person operation (FSQM-004). FSQM-018: the only rework is re-pouching (owner, 2026-10-29) and
-- FSQM-019 (draft) is withdrawn. FSQM-009/FSQM-023 agree on when a recall test raises a CAPA and when the
-- 24-hour notice runs; FSQM-024 agrees with the schedule on who leads the crisis test; FSQM-003 allows a
-- booked HACCP course to be Pending at designation, as FRM-005 already did. Forms other than FRM-702 change
-- labels, guidance, an option or an optional field only, with no revision change.

begin;

do $guard$
declare h text;
begin
  select md5(content::text) into h from public.sop_documents where id = '7d013a78-b499-4b0a-a883-327d5cdb7419' and status = 'active' and revision = 'v2';
  if h is distinct from 'e609e68ec248463fa9bfbbb5552efb19' then raise exception 'FSQM-018 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '9967ad2d-3cc9-46fd-99f2-85ccb5eef329' and status = 'active' and revision = 'v3';
  if h is distinct from 'f30cc03c268e91351f9299a356cdf623' then raise exception 'FRM-913 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '004c7945-4e18-4dd3-9fa8-e27f6d8c2b05' and status = 'active' and revision = 'v2';
  if h is distinct from '18240a5b0b10d891bfce58b3f37bba8a' then raise exception 'FSQM-023 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = 'a4dd00ae-f6ca-4214-a4f4-d19a98ddd660' and status = 'active' and revision = 'v2';
  if h is distinct from 'ef849a94f242d9509de230fc0713dc24' then raise exception 'FSQM-024 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '7717b881-1d6a-4bc7-9b54-41a8e3d1472c' and status = 'active' and revision = 'v2';
  if h is distinct from '2e39fa61eade3c256789baf8a947ab07' then raise exception 'FRM-702 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '6d069d17-c19f-4ef2-bbfd-1a9968046d81' and status = 'active' and revision = 'v3';
  if h is distinct from '16002e5fc1001eb199b52b97ea29a830' then raise exception 'FSQM-009 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '96b9eed2-3665-4857-a81c-b839d4f83f9d' and status = 'active' and revision = 'v6';
  if h is distinct from '8b063c51b607f8b657eea9a7f63e25c1' then raise exception 'FRM-903 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = 'a8388458-9e6c-4184-b41e-57fb4547c522' and status = 'active' and revision = 'v3';
  if h is distinct from 'e13e20ac78d5e63a17026e19bd34aece' then raise exception 'FRM-701 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '5e2f96fc-35f9-4842-877b-582ebe0c2896' and status = 'active' and revision = 'v4';
  if h is distinct from '866b16f28c34b247ae06ced189f1e736' then raise exception 'FSQM-003 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = '32e5fb32-ec41-4474-b6dc-3a8d377b8779' and status = 'active' and revision = 'v3';
  if h is distinct from '01e8dc0ddc6cb59ae6d9399e8d1421e9' then raise exception 'FRM-207 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where id = 'eb46f728-e635-45a7-9d46-7a9b501ed429' and status = 'active' and revision = 'v6';
  if h is distinct from '6617ea0c894329acd3cadb1f459a8fdf' then raise exception 'SOP-2.3.4 is not the document that was read (md5 %).', h; end if;
  if not exists (select 1 from public.sop_documents where id = '25a39c19-663f-4fca-8502-d405c0fb2a7e' and status = 'draft') then raise exception 'FSQM-019 is not the draft that was read.'; end if;
end $guard$;

update public.sop_documents set content = $jx${"scope": "This document applies to all raw materials, work in progress, finished products and equipment\nused and manufactured at Adventure Bakery, which may be suspected to be out of specification as a result of warehouse routine inspections, non-conforming production, Quality Control (QC) testing results, or customer complaints.", "purpose": "This procedure defines the identification, segregation and disposition of all raw materials, work\nin progress, finished product, and equipment suspected to be out of specification at Adventure Bakery.", "records": "FRM-702 Non-Conforming Material Hold & Tagging Record — one per hold. Identification of the material or equipment, the hold tag number, the segregated storage location, the final disposition and its authorisation.\nFRM-007 Corrective and Preventive Action (CAPA) Report — the investigation, where a CAPA is raised under FSQM-009. Its number is recorded on FRM-702 so the hold and the investigation are traceable to each other.\nFRM-205 Supplier Non-Conformance & Corrective Action Report (SCAR) — where the disposition is return to supplier. Its number is recorded in the Associated SCAR Number field on FRM-702.\nFRM-004 Equipment Register — the repair of non-conforming equipment, the confirmation that it can produce conforming product, its return to service, and the disposal of equipment that cannot be repaired.\nREP-701 QA Product & Material Release Log — the release of held or reworked material. Derived from FRM-702, so a release recorded there is listed without a further entry.\nBatch sheets — identify rework material and the formulation used, and carry its traceability.\nRetention: two years, or the shelf life of the product plus twelve months, whichever is longer. This is the period set by FSQM-009 Part 10, so a hold and the investigation arising from it are retained on the same basis.", "procedure": ["Upon completion of inspection and/or testing of raw material, work in progress, finished product samples, and equipment, the Quality Team shall determine whether the material or equipment conforms to specification, and shall record the result.", "Investigation of suspected non-conforming product can be initiated due to raw materials, intermediate materials, finished products, or equipment found to be non-compliant during receiving, storage, production, QC testing, shipping or routine food safety inspections.", "> Observation of product defect, damage or shelf life, QC result deviations, or customer complaints may lead to the disposition of a product as non-compliant.", "Upon identification of non-compliant raw material, work in progress material, finished product, or packaging material that can affect the quality, food safety or legality of a food product, any employee shall immediately notify the SQF Practitioner in order to place questionable material on Hold.", "Upon receipt of a customer complaint, the Quality Team shall establish with Admin the location of all remaining inventory of the suspected lot, and shall place suspect inventory on Hold.", "When the Quality Team is notified of suspected non-conforming material, or is working with a QC result that deviates from specifications, the questionable lot or batch shall be placed on Hold for investigation. For finished products, Product Sample Analysis records shall be reviewed for accuracy, completeness, and compliance.", "If a suspected material is found to be expired, damaged, or shows signs of contamination or infestation, the Quality Team shall place the lot on Hold upon notification.", "The Quality Team shall raise a Non-Conforming Material Hold & Tagging Record (FRM-702) immediately and notify the SQF Practitioner and the Management team of the incident.", "The Quality Team shall also label the Hold product or equipment with a hold tag and record the tag number, the material status and the segregated storage location on FRM-702.", "Production staff shall physically segregate the Hold product or equipment into the Quarantine area immediately to prevent accidental usage or shipping.", "Where non-conforming equipment cannot be moved to the Quarantine area, it shall be tagged where it stands and taken out of service. Equipment taken out of service shall not be used again until it is released under the repair step below.", "Admin shall complete the necessary transactions in the inventory system immediately.", "The Quality Team may determine a new sampling plan for further investigation of the product or equipment.", "Test and inspection results shall be provided to the SQF Practitioner for completion of the investigation, as applicable.", "A Corrective and Preventive Action shall be raised under FSQM-009 Corrective and Preventive Action (CAPA) Program and recorded on FRM-007. The CAPA number shall be recorded on FRM-702 so that the hold and its investigation are traceable to each other.", "> FSQM-009 Part 3 states when a CAPA is required, and non-conforming product is one of its triggers, so that decision is not taken again here. The investigation reviews the raw material records, batch sheets, lab records and any other documentation associated with the questionable lot. Root cause, the corrective and preventive actions with their owners and due dates, verification of effectiveness, closure and record retention are all governed by FSQM-009 and recorded on FRM-007. This procedure does not restate them, so the two documents cannot give different answers.", "The SQF Practitioner shall determine the final disposition of the product or equipment. FRM-702 records one of four outcomes: approved for production release, return to supplier, rework, or destruction and disposal.", "The Quality Team shall complete the Final Disposition and Release Authorization section of FRM-702, and the Management team shall be notified of the final disposition.", "Material shall be approved for production release only after the inspections and analyses relevant to the reason for the hold are complete, their results are acceptable and recorded, and the SQF Practitioner has authorised the release on FRM-702. The Quality Team shall then remove the hold tag, and Admin shall return the material to available stock in the inventory system. Released material is listed on REP-701 QA Product & Material Release Log.", "If the disposition is return to supplier, the Quality Team shall raise a Supplier Non-Conformance & Corrective Action Report (FRM-205) and record its number in the Associated SCAR Number field on FRM-702. Admin shall arrange the return under the approved supplier agreement terms and complete the necessary inventory transactions.", "If the disposition is destruction and disposal, Admin shall discard the held product or equipment, verify that the disposal is complete, and complete the necessary inventory transactions.", "• The only rework done on this site is re-pouching a unit whose vacuum seal failed (FSQM-016 step 13). It is part of the sealing step: the unit is re-pouched at once as the same product and lot, recorded on FRM-606, and needs no hold on FRM-702. No product is reworked into a new batch. If that ever changes, it is assessed under FSQM-007 and added to the food safety plan before it is done; the rules below then apply.", "If the SQF Practitioner determines that the product or equipment may be safe to rework, the product records and samples shall first be examined for food safety risks (micro, age, damage, etc.) before the rework decision is made.", "• All finished product rework shall be performed on a \"like into like\" basis.", "• The SQF Practitioner shall determine the rework formulation, with careful consideration to product specifications, functionality and potential impact on product performance. The rework material and the formulation used shall be clearly identified in the batch sheet and traceable.", "• Reworked product shall be processed in accordance with the site's food safety plan. Rework shall not be used where it would affect the safety or integrity of the finished product.", "• Rework quantities in the Quarantine Area shall be reviewed every two weeks at a minimum by the Quality Team to ensure rework inventory is maintained at a minimum level. Review shall consider manufacturing dates and product age, possible packaging damage, infestation, microbial risk and other food safety concerns. Some products may need to be retested to determine an appropriate rework formulation, if necessary.", "• Each batch of reworked material shall be inspected or analyzed against the finished product specification before release, and shall then be released under the release requirements of this procedure - recorded on FRM-702 and listed on REP-701.", "Non-conforming equipment shall not be returned to service until the repair is complete and the SQF Practitioner has confirmed that the equipment is capable of producing product that meets specification. The repair, that confirmation and the return to service shall be recorded against the equipment on FRM-004 Equipment Register, as shall the disposal of equipment that cannot be repaired.", "The hold is closed when the final disposition is complete and recorded on FRM-702. A CAPA raised from the hold remains open under FSQM-009 until its actions are verified effective; the two are tracked separately, because FSQM-009 requires the disposition of affected product to be resolved before a CAPA can be closed.", "Hold inventory in the Quarantine warehouse shall be reviewed biweekly by the Quality Team to ensure rework materials are processed in a timely manner as permitted by product demand."], "attachments": [{"name": "SOP_FSQM-018_0001.docx", "path": "7d013a78-b499-4b0a-a883-327d5cdb7419/files/SOP_FSQM-018_0001.docx"}], "definitions": "Quarantine Area: Warehouse designated for the segregation of hold, rejected and rework inventory at Adventure Bakery.", "responsibility": "SQF Practitioner — owns this procedure. Decides what is placed on Hold, determines the final disposition of held product and equipment, determines rework formulations, confirms each batch of reworked material meets the finished product specification before release, authorises the release of held material, and confirms that non-conforming equipment is capable of producing conforming product before it returns to service. Raises and owns any CAPA arising, under FSQM-009.\nQuality Team — places suspect material on Hold, raises and completes FRM-702, applies the hold tag, sets any additional sampling, and reviews held and rework inventory biweekly.\nAll staff — report suspected non-conforming material to the SQF Practitioner immediately. No employee is disadvantaged for raising one.\nProduction staff — segregate held product and equipment into the Quarantine area on notification, and store it so that it cannot be used or shipped.\nManagement team — is notified of every hold and of its final disposition, and is responsible for the resources needed to hold, rework or dispose of material.\nAdmin — completes the inventory transactions for held, reworked and scrapped material, discards material on a disposal disposition, arranges returns to suppliers under the approved supplier agreement terms, returns released material to available stock, and locates the remaining inventory of a suspect lot on request.", "form_references": "FRM-702 Non-Conforming Material Hold & Tagging Record; FRM-007 Corrective and Preventive Action (CAPA) Report; FRM-205 Supplier Non-Conformance & Corrective Action Report (SCAR); FRM-004 Equipment Register; REP-701 QA Product & Material Release Log", "revision_history": "Rev New — imported 2026-06-17 from a scanned hardcopy of the Compass Blending original through the Word importer. DRAFT. Not approved, not in force, and not yet reconciled with the programs issued around it.\n\nFORMATTING AND OCR REPAIR, 2026-09-02. Presentation only. The stored body was raw importer output and did not print: it was 41 lines carrying the source document's own numbering, which the renderer numbered a second time on top. No requirement was added, removed or reworded in that pass, with the two exceptions recorded under RECONSTRUCTIONS below. What changed:\n\n• The source numbering was removed from every step. The rendered list owns the numbering now, which is how every other document here is stored. Nothing else in the body cites a step number, so nothing was left pointing at an old one.\n\n• The document was flattened to one level. The renderer has exactly two: a numbered step, and a list item or paragraph beneath it. The source ran three deep (2, 2.1, 2.1.1), so the sub-steps of the hold triggers and of the rework rules were promoted to steps and to bullets respectively. The reading order is unchanged; only the depth is.\n\n• Three steps had been split across a scan page break and were rejoined: \"...finished product / samples, and equipment\", the gluten-free segregation step, and \"...gluten results / >10ppm shall not be reworked\".\n\n• Two steps had been merged into one line, which also carried a stray OCR character (\"n 6.4 ... 6.5 ...\"). They are two steps again — labelling the Hold product, and segregating it into Quarantine — and the stray character is gone.\n\n• The running header \"NON-CONFORMING PRODUCT\" appeared twice in the middle of the body as though it were a step. Both were removed.\n\n• The four Root Cause Analysis criteria (Food Safety risk, product quality impact, service impact, cost) were unmarked and so printed as four numbered steps. They were marked as the list they are; they have since been removed altogether — see CORRECTIVE ACTION below.\n\nTHE HOLD RECORD IS NAMED. Linked Form read \"Form-0021 Quality Hold Report\", a Compass Blending number that does not exist in this register, and the body called that record a \"Hold Action Report\" in three steps. Both now name FRM-702 Non-Conforming Material Hold & Tagging Record, which is active. This is not a find-and-replace on a similar-sounding title: FRM-702's three sections are the three moments this procedure describes. Section 1 Initial Hold Identification raises the hold and carries the hold tag number, the material status and the segregated storage location, which is what the \"issue a report\" and \"label with a tag\" steps do. Section 3 Final Disposition and Release Authorization carries the disposition decision, its justification, a verification check and an authorising signature, which is what the \"revise the report\" step does. The three steps now say which section they complete.\n\nOne limitation of that mapping, which is a question about the form rather than about this procedure: FRM-702 Section 1 is written around material received from a supplier — Supplier Name, P.O. Number, Supplier Lot / Batch Number. This procedure also covers work in progress and finished product, where those fields have no answer. They are not marked required, so an internal hold can be recorded today with them left blank, but the form should be reviewed against the wider scope before this document is issued.\n\nROLES, 2026-09-02. This changes who does what. It is not a formatting pass.\n\nThe body named eleven actors: QC personnel, Quality personnel, Quality Technicians, Quality Leader, Quality Management, Plant Manager, Production associate, Warehouse personnel, R&D, the Customer Services and Sales Supply specialist, and \"the appropriate functional area manager\". That is a Compass Blending organisation chart. None of those posts exists here, so no responsibility in this document was assigned to anybody. They are replaced by the six roles the issued programs already use — SQF Practitioner, Quality Team, Management team, Production staff, Admin and All staff — so that FSQM-009, FSQM-012, FSQM-013, FSQM-022 and this document describe one organisation rather than two. As in those documents, no individual is named: a document that names a person has to be reissued when the person changes.\n\n• QC personnel, Quality personnel and Quality Technicians become the Quality Team.\n• Quality Leader and Quality Management become the SQF Practitioner.\n• Plant Manager, and the bare \"Management\", become the Management team.\n• The Production associate becomes All staff, matching FSQM-009, which already says any employee may raise a non-conformance and must report it immediately.\n• Warehouse personnel become Production staff. There is no separate warehouse function.\n• The Customer Services and Sales Supply specialist becomes Admin.\n• \"The appropriate functional area manager\" becomes the SQF Practitioner, which is what FSQM-009 Part 5 already says.\n• R&D becomes the SQF Practitioner. The site confirmed on 2026-09-02 that the SQF Practitioner and R&D are the same person.\n\nTHREE STEPS DID NOT SURVIVE THE SUBSTITUTION, and rewriting them is why this was not done as a find-and-replace. Each described a hand-off between two posts that turn out to be one person, and a step nobody can evidence is worse than no step at all.\n\n• Step 7 required the incident to be communicated to four named parties. After substitution that list is the SQF Practitioner and the Management team, and it read as an instruction to notify oneself. It is now one sentence — raise FRM-702, notify the SQF Practitioner and the Management team — and the four-name list is deleted.\n\n• Final disposition was given to \"the Plant Manager and Quality Leader\", written as two posts agreeing. It is the SQF Practitioner alone. A quorum of one is not a control, and writing it as though it were invites an auditor to test a separation of duties that does not exist.\n\n• The rework formulation was determined by R&D and then communicated by R&D to the Plant Manager. Both are the same person. The two steps are merged into one, which keeps what SQF 2.4.6.1 actually requires — a qualified person determines the formulation, and the material and formulation are identified in the batch sheet and traceable — and drops only the hand-off.\n\nCORRECTIVE ACTION NOW DEFERS TO FSQM-009 INSTEAD OF RESTATING IT. Four steps covered root cause analysis, when an analysis is done, records, and verification of effectiveness. FSQM-009 Corrective and Preventive Action (CAPA) Program was issued on 2026-09-02 and governs all four, and the two documents had already diverged on both of the things that matter:\n\n• This procedure said root cause analyses are conducted \"at Management discretion\" based on food safety risk, product quality impact, service impact and cost. FSQM-009 Part 3 lists ten triggers and non-conforming product is one of them. As written, this document permitted skipping an investigation that FSQM-009 requires, and an auditor holding both would fairly take the weaker rule as the site's practice. The four discretion criteria are removed; when a CAPA is raised is FSQM-009's decision, in one place.\n\n• This procedure gave verification of effectiveness to the Plant Manager and Quality Leader. FSQM-009 gives it to the SQF Practitioner, or to someone independent of the action owner. There is now one answer, in one document.\n\nThe investigation steps are replaced by a reference: a CAPA is raised under FSQM-009, recorded on FRM-007, and its number is written onto FRM-702 so the hold and the investigation are traceable to each other. FRM-702 had nowhere to hold that number — Section 2 offered only an Associated SCAR Number, which a CAPA is not — so it gains an Associated CAPA Number field in migration 20260902000012, taken now while it still has zero entries. This is the gap FRM-908's car_ref had and the fix FRM-913 received in the same wave.\n\nTHE HOLD DOES NOT WAIT ON THE CAPA. FSQM-009 Part 8 cannot close a CAPA until the disposition of affected product is resolved. Requiring the hold to stay open until its CAPA closes would deadlock the two documents against each other, so the closing step says plainly that the hold closes on final disposition and the CAPA continues separately under FSQM-009.\n\nThat pass left the body at 27 lines: 19 steps, 6 list items and 2 paragraphs.\n\nRECONSTRUCTIONS — two places where the scan was not legible and the text was repaired rather than transcribed. Both were resolved at issue, the first by removing the reconstruction rather than adopting it:\n\n1. The GFCO notification address read \"testing(4Iuten.org\", which is not an address. The draft carried testing@gluten.org as a reconstruction awaiting confirmation. AT ISSUE THE INVENTED ADDRESS WAS REMOVED rather than adopted: the step now says to notify GFCO using the contact details in the current GFCO certification agreement. An active controlled document must not assert a fact nobody has verified, and a certifier's contact details change without this document being revised, so the agreement is the better authority in any case.\n\n2. The cross-reference \"steps described in sections 6.3 thru 6.11\" pointed at the source document's numbering, which no longer exists anywhere in this document. It reads \"the hold, notification and segregation steps set out below\". ADOPTED AT ISSUE as written; the descriptive form cannot go stale the way a numeric range can. If a narrower range was meant, it is a revision to make against the paper original.\n\nOne further wording change: step 1 read \"Quality personnel shall dispose of the product inspected/tested\", which on its face directs that everything inspected be thrown away. Read in context it means a disposition decision, and it was written as \"shall determine the disposition of\", then narrowed again by the pre-activation vetting to determining whether the material conforms. ADOPTED AT ISSUE: the literal reading directed that everything inspected be thrown away, which no procedure can have meant.\n\nPRE-ACTIVATION VETTING, 2026-09-02. Activation was held back and the document was read clause by clause against the code, and step by step against the record it writes to. Four gaps were found and closed. Still draft.\n\n1. THE PROCEDURE EXPLAINED TWO OF THE FOUR DISPOSITIONS ITS OWN RECORD OFFERS. FRM-702's Final Disposition Decision is a four-option field — approved for production release, return to supplier, rework, destruction and disposal — and only rework and disposal had steps. Release is the most common outcome of a hold and the one SQF 2.4.7.1 governs, and nothing stated the conditions for it, who removes the hold tag, or how material returns to stock. Return to supplier had no step at all, although FRM-205 exists for it and FRM-702 carries an Associated SCAR Number field that nothing filled. Both steps are added, and the final-disposition step now names all four outcomes so the procedure and the form cannot be read apart.\n\n2. THE INTENDED CLAUSE REFERENCE OVERCLAIMED 2.4.6.1. Food Manufacturing 2.4.6.1 has seven limbs. Limb iii — reworked product processed in accordance with the site's food safety plan — was not in the document at all, and limb iv wants EACH BATCH inspected or analyzed before release where the text said \"as needed\". Both are now written. Limb vi requires release of reworked product to conform to 2.4.7, which is what the new release step provides. Claiming a clause that is only partly met is worse than claiming fewer, because it tells an auditor where to look.\n\n3. \"POSITIVE RELEASE PROCEDURE\" IS NO LONGER CITED. The rework rules made it the authority for the final disposition of reworked material, and no document of that name exists anywhere in the register — it was a Compass Blending reference that survived the import. Reworked material is now released under the release requirements of this procedure, recorded on FRM-702 and listed on REP-701. What remains unowned is a site-wide finished-product release procedure and a positive release procedure based on pathogen or chemical testing (2.4.7.3); neither is in this document's scope, and this document no longer implies they exist.\n\n4. NON-CONFORMING EQUIPMENT HAD NOWHERE TO GO AND NO WAY BACK. 11.1.7.9 requires equipment to be identified, tagged and/or segregated for repair or disposal, with records maintained. Segregation into a Quarantine warehouse is written for material; a mixer cannot be carried there, which is why the clause says \"and/or\". A step now covers tagging equipment where it stands and taking it out of service, and a second covers repair, the SQF Practitioner's confirmation that it can produce conforming product, and its return to service. Equipment records go to FRM-004 Equipment Register, not to FRM-702 — FRM-702's fields are Material Name, Supplier Name, P.O. Number and Supplier Lot, and its dispositions have no \"repaired and returned to service\", so recording a broken machine there would have been a record in name only.\n\n5. Step 1 gave the Quality Team \"determine the disposition\" while the final-disposition step gave it to the SQF Practitioner. Step 1 now determines whether the material or equipment conforms, and records the result.\n\nLinked Form now lists all five records the procedure requires: FRM-702, FRM-007, FRM-205, FRM-004 and REP-701. Body: 27 lines become 32 — 23 steps, 7 list items, 2 paragraphs.\n\nISSUED 2026-09-02, approved GJM. Status active, revision New — a first issue, not a revision, so nothing is superseded and nothing is archived.\n\nSETTLED AT ISSUE. Records, Governing Reference and the SQF clause reference were empty, and a controlled document with no stated records and no clause reference cannot be audited against anything. All three are now filled. The clause reference is 2.4.5.1, 2.4.5.2, 2.4.6.1, 11.1.7.9 — 11.1.7.9 covering non-conforming EQUIPMENT specifically, which this document's title claims and which nothing else here covers, and 2.4.6.1 claimed only because the pre-activation vetting wrote in its limbs iii and iv rather than leaving them uncovered. 2.4.7 Product Release is deliberately NOT claimed: this document releases held and reworked material, not the site's finished product generally. Records name FRM-702, FRM-007, FRM-205, FRM-004, REP-701 and the batch sheets, and set retention at two years or shelf life plus twelve months, which is FSQM-009 Part 10's period: a hold and the investigation arising from it should not be retained on two different bases. Governing Reference names FSQM-019 for the reader but does not cite it as governing, because it is still an unapproved draft.\n\nREWORK AUTHORITY SETTLED, which is what allowed this to be issued. FSQM-019 gave rework authority to the R&D Manager where this document gives it to the SQF Practitioner. Two documents naming different authorities for one decision is a document-control problem under SOP-2.2.3 regardless of which is right, and issuing over a live draft that contradicted this one would have created a finding rather than closed one. The site decided on 2026-09-02 in favour of the SQF Practitioner, and FSQM-019 was aligned in migration 20260902000015 — it now defers to this document for the substantive rework rules instead of restating them.\n\nSTILL OPEN AFTER ISSUE — none of it a defect in this document, and none of it in its scope:\n\n1. FSQM-019 Rework Procedure remains an unapproved draft. It no longer contradicts this document, but it is thin — four steps, no Records, no clause reference — and it is a candidate for withdrawal in favour of this document's rework section rather than issue. That decision blocks nothing.\n\n2. Not in this document's scope but adjacent and unowned: there is no site-wide product release procedure (2.4.7 Product Release is Mandatory in the Food Manufacturing code), no positive release procedure based on pathogen or chemical testing (2.4.7.3), and no returned-product procedure (Quality Code 2.4.5.3). This document releases held and reworked material only, and says so.\n\nUNTIL THIS DOCUMENT IS ISSUED it is not in force, whatever it now says. FRM-702 is active and is the record actually in use for holding and tagging non-conforming material, and FSQM-009 governs the corrective action that follows. That is the position FSQM-009's own Scope states, and naming FRM-702 here does not change it.\n\nRev v2 — 2026-09-09, approved GJM. REMOVES THREE STEPS FOR A PRODUCT THE SITE HAS NEVER MADE. Rev New carried a bullet routing positive gluten results (>10 ppm) into the hold steps, an instruction to notify GFCO using the contact details in \"the current GFCO certification agreement\", and a rework sentence about segregated certified Gluten Free product. The Managing Partner confirmed on 2026-09-09 that Adventure Bakery has never produced a product carrying a Gluten Free claim and holds no current GFCO certification. There is no certification agreement to consult and no certified product to segregate.\n\nThey are removed rather than reworded, on the reasoning this site already used when FSQM-020 was issued with its bulk-product Part removed: a step describing something that never happens is worse than no step at all, because it is the first thing an auditor tests and the first thing the floor learns to ignore. This one is worse still — it directs the SQF Practitioner to a document that was never held.\n\nNothing is orphaned. Both removed bullets sat under the general hold rule, which is unchanged: any employee finding non-conforming material notifies the SQF Practitioner and the material goes on Hold. Only the second sentence of the rework step is gone; \"All finished product rework shall be performed on a like into like basis\" is a real rule and stays.\n\nThis is the same standard Rev New applied to the damaged GFCO notification address, which was removed rather than reconstructed because \"an active controlled document must not assert a fact nobody has verified\". That was right about the address. The certification behind it went unexamined, and this corrects it. The likeliest source is the Compass Blending hardcopy this document was scanned from — the import rebrands the company name across every parsed string, but cannot know the content belongs to a different business. FSQM-020 carried the same assumption and is corrected by 20260909000007.\n\nv3 - 2026-10-29 - States that the only rework on site is re-pouching a failed seal (part of the sealing step, recorded on FRM-606, no hold), and that no product is reworked into a new batch (owner, 2026-10-29). The draft FSQM-019 Rework Procedure is withdrawn. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 2.4.5 Non-conforming Materials and Product; 2.4.6 Product Rework; 11.1.7.9 non-conforming equipment.\nSQF Quality Code, Edition 9 — 2.4.5 Non-conforming Product or Equipment; 2.4.6 Product Rework.\nFSQM-009 Corrective and Preventive Action (CAPA) Program — governs the investigation, root cause, corrective and preventive action, verification of effectiveness and closure of any CAPA raised from a hold under this procedure."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '7d013a78-b499-4b0a-a883-327d5cdb7419' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-913-GMP-Food_Safety_Inspection_Record.docx", "path": "9967ad2d-3cc9-46fd-99f2-85ccb5eef329/files/FRM-913-GMP-Food_Safety_Inspection_Record.docx"}, {"name": "FRM-913-GMP-Food_Safety_Inspection_Record.pdf", "path": "9967ad2d-3cc9-46fd-99f2-85ccb5eef329/files/FRM-913-GMP-Food_Safety_Inspection_Record.pdf"}], "form_schema": {"sections": [{"id": "details", "title": "Inspection", "fields": [{"id": "inspection_date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "inspection_type", "type": "select", "label": "Type", "width": "third", "options": ["Routine (monthly)", "Follow-up", "Pre-audit", "Other"], "required": true, "showInList": true}, {"id": "areas_covered", "type": "text", "label": "Areas covered", "width": "third", "showInList": true}, {"id": "inspectors", "help": "Quality Team members present, and any hourly employee accompanying the inspection", "type": "text", "label": "Inspection team", "width": "full"}]}, {"id": "how_to", "title": "How to use this form", "fields": [{"id": "how_to_note", "text": "One row per SQF Module 11 subsection, with the clause range it covers. Walk the site and mark each row Pass, Fail, or N/A.\n\nPass — observed and conforming. Fail — record what was seen in Finding, and the correction, who owns it and by when in Corrective action. N/A — the subsection does not apply to this site; say WHY in the Finding column, because 2.4.2.1 permits exempting a Module 11 requirement only on a written risk analysis, and these N/A rows with their reasons are what that analysis is built from.\n\nA blank row is not the same as a Pass. Every row is answered before the inspection is signed off.", "type": "info", "label": "How to use this form"}]}, {"id": "sec_11_1", "title": "11.1 Site Location and Premises", "fields": [{"id": "check_11_1", "rows": {"mode": "fixed", "labels": ["11.1.1 Premises Location and Approval  (11.1.1.1)", "11.1.2 Building Materials  (11.1.2.1–.9)", "11.1.3 Lighting and Light Fittings  (11.1.3.1–.3)", "11.1.4 Inspection/Quality Control Area  (11.1.4.1)", "11.1.5 Dust, Insect, and Pest Proofing  (11.1.5.1–.3)", "11.1.6 Ventilation  (11.1.6.1–.4)", "11.1.7 Equipment and Utensils  (11.1.7.1–.9)", "11.1.8 Grounds and Roadways  (11.1.8.1–.3)"], "addLabel": "Add item", "guidance": ["• Anything nearby that could threaten product: neighbouring businesses, dumpsters, standing water, overgrowth\n• Any risk found is controlled, and the assessment is updated when the surroundings change\n• The building is approved/permitted to operate", "• Floors smooth, sealed, free of cracks and pooled water; they drain properly\n• Drains clean and not a trip or contamination hazard\n• Walls, ceilings and doors durable, smooth, light-coloured and clean; wall-to-floor corners sealed\n• No pipes or ducting over product that could drip or shed\n• Windows shatterproof; doors solid\n• Ceiling (or drop ceiling) intact, no missing tiles or gaps\n• Stairs or platforms, if any, are not over open product", "• Enough light to work and inspect by\n• Lights over exposed product, ingredients or packaging are shatterproof or covered, with no cracked or missing covers\n• Warehouse lights protected from breakage", "• If product is inspected on the line: the spot is clean, has handwashing nearby and a waste bin\nN/A if there is no inspection station on the line - say so in Finding.", "• Outside doors and windows seal when closed - no daylight at the gaps\n• Personnel doors close themselves and are insect-proofed\n• Dock/overhead doors: self-closing, screen, air curtain or good seal\n• Traps and bait stations placed where they cannot contaminate product, packaging or equipment\n• No poison bait inside production or storage areas", "• Enough airflow; no condensation build-up\n• Vents and fans clean and screened against insects\n• Hood/extraction over heat and steam sources (oven, kettle) works and is clean", "• Equipment in good repair: smooth, no cracks, rust, flaking paint or crevices that trap food\n• Tables, benches and machines placed so they can be cleaned around\n• Utensils and containers stored clean and off the floor; food-contact kept apart from non-food\n• Waste bins clearly marked\n• Broken equipment tagged or set aside so nobody uses it\n• Carts, pallet jacks or other vehicles in production are clean and not a hazard", "• Outside kept free of rubbish, clutter, stored junk and overgrowth that would attract pests\n• No pooled water at the loading area; outside drains clear\n• Paths into the building sealed, not bare dirt"], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.1 Site Location and Premises", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_2", "title": "11.2 Site Operation", "fields": [{"id": "check_11_2", "rows": {"mode": "fixed", "labels": ["11.2.1 Repairs and Maintenance  (11.2.1.1–.8)", "11.2.2 Maintenance Staff and Contractors  (11.2.2.1–.3)", "11.2.3 Calibration  (11.2.3.1–.6)", "11.2.4 Pest Prevention  (11.2.4.1–.6)", "11.2.5 Cleaning and Sanitation  (11.2.5.1–.9)"], "addLabel": "Add item", "guidance": ["• No temporary fixes (tape, cardboard, wire) left in place without a plan to repair them\n• Recent repairs cleaned up after; supervisor was told before work in production areas\n• Lubricant on or over food-contact equipment is food-grade\n• Paint in production areas intact, not flaking, and not on product-contact surfaces\n• Equipment failures are recorded and the repair is on the maintenance schedule", "• Contractors and maintenance staff follow the same hygiene rules (hair net, no jewellery, handwashing)\n• Contractors not trained on site food safety rules are escorted\n• No tools, screws, wire or debris left behind after a job", "• Scales, thermometers and other measuring devices are on the calibration list and within date\n• Devices protected from damage and not adjusted by unauthorised people\n• If a device was found out of calibration: the product it measured was assessed", "• No signs of pests: droppings, gnaw marks, insects, nests, webs\n• Traps and bait stations in place, numbered, matching the site map, not damaged or overdue\n• Pest control visit reports current; any activity found has been acted on\n• Pesticides, if kept on site, labelled and stored with the chemicals\n• No animals in food handling or storage areas", "• Equipment and areas clean to the eye, including under, behind and above\n• Daily sanitation and pre-op records (FRM-903) filled in and current\n• Sani-512 mixed to 200 ppm; test strips on hand and the check is recorded\n• Only approved chemicals present; containers labelled\n• Cleaning tools marked, stored off the floor, in good condition\n• Toilets, break room and change areas clean"], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.2 Site Operation", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_3", "title": "11.3 Personnel Hygiene and Welfare", "fields": [{"id": "check_11_3", "rows": {"mode": "fixed", "labels": ["11.3.1 Personnel Welfare  (11.3.1.1–.2)", "11.3.2 Handwashing  (11.3.2.1–.6)", "11.3.3 Clothing and Personal Effects  (11.3.3.1–.8)", "11.3.4 Visitors  (11.3.4.1–.4)", "11.3.5 Staff Amenities (change rooms, toilets, break rooms)  (11.3.5.1–.10)"], "addLabel": "Add item", "guidance": ["• Nobody working with exposed food while visibly ill\n• Cuts covered with a coloured, metal-detectable bandage; a glove over it if on the hand\n• Staff know to report illness and what to do if blood or bodily fluid gets on a surface", "• Watch people wash hands: on entering production, after toilet, eating, smoking, cleaning or handling waste\n• Handwash sinks near entrances: hot and cold water, soap in a dispenser, paper towels, a bin\n• Sinks used only for handwashing, not blocked or used for storage\n• Handwashing signs posted in the languages staff read\n• People wearing gloves still wash hands", "• Uniforms and shoes clean at the start of the shift; heavily soiled clothing changed\n• Hair nets and beard covers worn and covering all hair\n• No jewellery apart from plain bands or medical alert items, covered\n• Gloves and aprons changed after breaks and when damaged; not left on product, packaging or equipment\n• Racks for aprons/smocks by the entrance, used when leaving production\n• Phones and personal belongings kept in lockers or offices, not in production", "• Visitors signed in and acknowledged the GMP rules (FRM-905 / FRM-906)\n• Visitors escorted or briefed; wearing hair nets and suitable clothing; jewellery removed\n• Visitors come in through the staff entrance and wash hands\n• No visibly ill visitors in production", "• Toilets clean, stocked and separate from production; handwash sink right by them\n• Street clothes and personal items stored away from uniforms, food and packaging\n• Change area clean\n• Break room separate from production, clean, with a fridge and sink; no food waste left out\n• Outside eating/smoking area clean and not attracting pests"], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.3 Personnel Hygiene and Welfare", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_4", "title": "11.4 Personnel Processing Practices", "fields": [{"id": "check_11_4", "rows": {"mode": "fixed", "labels": ["11.4.1 Staff Engaged in Food Handling and Processing Operations  (11.4.1.1–.4)"], "addLabel": "Add item", "guidance": ["• People enter production through the personnel door only; doors kept closed\n• No eating, drinking, gum or tasting product in production (except controlled sensory testing)\n• No false nails, nail polish, long nails or false eyelashes when handling exposed food\n• No product, packaging or utensils placed on the floor\n• Staff don't move from dirty areas (waste, raw materials) to finished product without washing up\n• Dropped product discarded, not put back"], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.4 Personnel Processing Practices", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_5", "title": "11.5 Water, Ice, and Air Supply", "fields": [{"id": "check_11_5", "rows": {"mode": "fixed", "labels": ["11.5.1 Water Supply  (11.5.1.1–.6)", "11.5.2 Water Treatment  (11.5.2.1–.3)", "11.5.3 Water Quality  (11.5.3.1–.3)", "11.5.4 Ice Supply  (11.5.4.1–.3)", "11.5.5 Air and Other Gases  (11.5.5.1–.2)"], "addLabel": "Add item", "guidance": ["• Hot and cold water available at every sink needed for cleaning\n• Hoses stored off the floor; no hose ends sitting in buckets or drains (back-siphonage)\n• Backflow preventers in place; annual backflow test current where applicable\n• Any non-potable water lines clearly marked and not connected to potable\n• Staff know what to do if the water supply is declared unsafe", "• If water is filtered or treated on site: equipment working, filters changed on schedule, checks recorded\nN/A if the site uses municipal water with no treatment - say so in Finding.", "• Water testing result on file and within the last 12 months\n• Result meets potable water standards", "• If ice is used in the process or as an ingredient: made from potable water, from an approved supplier, stored in a clean covered container, scoop kept out of the ice\nN/A if no ice is used - say so in Finding.", "• If compressed air or another gas touches food or food-contact surfaces: filters maintained and quality checked at least annually\nN/A if no air or gas touches food or food-contact surfaces - say which uses were checked."], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.5 Water, Ice, and Air Supply", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_6", "title": "11.6 Receipt, Storage, and Transport", "fields": [{"id": "check_11_6", "rows": {"mode": "fixed", "labels": ["11.6.1 Receipt, Storage, and Handling of Goods  (11.6.1.1–.6)", "11.6.2 Cold Storage, Freezing, and Chilling of Foods  (11.6.2.1–.4)", "11.6.3 Storage of Dry Ingredients, Packaging, and Shelf Stable Packaged Goods  (11.6.3.1–.2)", "11.6.4 Storage of Hazardous Chemicals and Toxic Substances  (11.6.4.1–.7)", "11.6.5 Loading, Transport, and Unloading Practices  (11.6.5.1–.8)"], "addLabel": "Add item", "guidance": ["• Goods stored off the floor and away from walls so the space can be inspected and cleaned\n• Oldest stock used first; nothing past its date\n• Raw materials kept apart from finished product; allergens stored so they cannot spill onto other goods\n• Open ingredients covered and labelled\n• Anything in overflow or temporary storage is protected and the risk is considered", "• Fridge and freezer at temperature; sensors reporting\n• Temperature records and any alerts reviewed and acted on (FRM-401)\n• Units clean, not overloaded, door seals intact, no ice build-up\n• Condensate and defrost water drains to a drain, not onto product or the floor", "• Dry storage away from wet areas, clean and dry\n• Packaging protected from dust and pests; no damaged or open cases\n• Racks cleanable, with room to see and clean floors and behind racks\n• Nuts kept in closed, labelled containers on the allergen rack, below other materials and never above them (FSQM-027, SQF 2.8.1.3)", "• Chemicals in a marked, lockable area away from food and packaging\n• Every container labelled with what is in it; no chemicals in food containers\n• Safety Data Sheets current and available\n• Food-grade and non-food-grade chemicals not mixed together\n• Spill kit and PPE on hand; empty containers not reused", "• Vehicle check done before loading and recorded (FRM-801)\n• Loading area clean; product not left sitting exposed during loading\n• Loaded vehicle secured with a latch, lock or seal"], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.6 Receipt, Storage, and Transport", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_7", "title": "11.7 Separation of Functions", "fields": [{"id": "check_11_7", "rows": {"mode": "fixed", "labels": ["11.7.1 High-Risk Processes  (11.7.1.1–.5)", "11.7.2 Thawing of Food  (11.7.2.1–.3)", "11.7.3 Control of Foreign Matter Contamination  (11.7.3.1–.9)", "11.7.4 Detection of Foreign Objects  (11.7.4.1–.5)"], "addLabel": "Add item", "guidance": ["• If a high-risk process exists (product handled after a kill step and not cooked again before eating): area separated, dedicated staff, clothing change on entry\nN/A if there is no high-risk process on site - say so in Finding.", "• If product or ingredients are thawed: done in a suitable place and way (refrigerated, or controlled air/water), not on the floor or at room temperature uncontrolled\n• Packaging from thawed product disposed of promptly\nN/A if nothing is thawed - say so in Finding.", "• No glass, ceramic or brittle plastic items in production that are not on the glass & brittle plastic register\n• Items on the register are intact\n• Nothing loose on equipment or overhead: nuts, bolts, screws, tape, cable ties\n• Knives controlled and in good condition; no snap-off blades anywhere\n• Wooden pallets or utensils in production are clean and not splintering\n• Gaskets, belts, seals and scrapers not worn or shedding pieces", "• If a metal detector, sieve, screen or filter is used: working, checked at the set frequency, and checks recorded\n• Rejected or contaminated product isolated and its disposition recorded\nN/A for the detector limb if no detection or removal device is used - say so in Finding."], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.7 Separation of Functions", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "sec_11_8", "title": "11.8 Waste Disposal", "fields": [{"id": "check_11_8", "rows": {"mode": "fixed", "labels": ["11.8.1 Waste Disposal  (11.8.1.1–.10)"], "addLabel": "Add item", "guidance": ["• Waste removed regularly; not building up in production\n• Bins clean, lidded where needed, clearly marked as waste\n• Outside dumpster area clean, lids closed, not attracting pests\n• Liquid waste goes to a drain or a lidded container\n• Packaging with our brand or customer brands disposed of so it can't be misused"], "deletable": true, "labelHeader": "Module 11 subsection"}, "type": "grid", "label": "11.8 Waste Disposal", "columns": [{"id": "conforms", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "finding", "type": "text", "label": "Finding / observation", "width": 3}, {"id": "action", "type": "text", "label": "Corrective action, owner & due date", "width": 3}, {"id": "capa_no", "type": "text", "label": "CAPA No.", "width": 1}], "rowDialog": true}]}, {"id": "summary", "title": "Findings & Sign-Off", "fields": [{"id": "findings_count", "type": "number", "label": "Number of findings raised", "width": "third", "showInList": true}, {"id": "na_count", "help": "These feed the Module 11 exemption analysis required by 2.4.2.1", "type": "number", "label": "Rows marked N/A", "width": "third"}, {"id": "repeat_findings", "type": "pass_fail", "label": "Any repeat findings from last inspection?", "width": "third"}, {"id": "summary_notes", "type": "textarea", "label": "Summary, trends and anything referred to Maintenance", "width": "full"}, {"id": "all_assigned", "type": "pass_fail", "label": "Every finding has a corrective action, an owner and a due date", "width": "half", "required": true}, {"id": "inspector_sig", "type": "signature", "label": "Inspection led by", "width": "half"}, {"id": "management_sig", "type": "signature", "label": "Reviewed at management review", "width": "half"}, {"id": "review_date", "type": "date", "label": "Management review date", "width": "half"}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "{inspection_date} — GMP / Food Safety Inspection"}}, "revision_history": "v3 - 2026-10-29 - The 11.6.3 storage row's guidance includes the allergen segregation check FSQM-027 places here. Guidance only; no revision change."}$jx$::jsonb,
       revision = 'v3'
 where id = '9967ad2d-3cc9-46fd-99f2-85ccb5eef329' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "All product made on site. The site packs under its customers' brands and every customer collects from the site, so a recall is carried out together with the brand owner. Crises that stop the site from making safe food are covered by FSQM-024.", "purpose": "This program states who starts and runs a product withdrawal or recall, how affected product is found and brought back, who is told and how fast, and how the system is tested every year.", "records": "• FRM-012 - one per mock recall and one per actual withdrawal or recall\n• FRM-011 - the current contact list\n• FRM-007 CAPAs raised from a test or an event", "procedure": ["When this program starts", "• A withdrawal or recall is considered whenever product that has left the site may be unsafe or wrongly labelled: an illness or allergen complaint, a supplier's recall or allergen notice, a CCP deviation or failed release check found after dispatch, a labelling error, or a request from a regulator or from the customer whose brand is on the pack.", "• Whoever learns of it tells Senior Site Management at once. Senior Site Management decides the same day whether to start, and is responsible for initiating and managing the withdrawal or recall; the SQF Practitioner investigates it (SQF 2.6.3.1 i).", "The first steps - the same day", "• Hold: affected product and materials still on site are put on hold on FRM-702 under FSQM-018.", "• Trace: the SQF Practitioner traces the affected lots under FSQM-021 - FRM-520 for the supplier lots in each finished lot, FRM-301 for their receipt, FRM-801 for every customer who collected the lot, how much and when. This is the essential traceability information, and the target is to have it within 4 hours (SQF 2.6.3.1 ii). The Traceability page of the Team Portal, and the FRM-012 record itself, pull these records together from a supplier lot or from one of our lot codes and list what the records do not show; the SQF Practitioner checks the result against the records.", "• Record: an FRM-012 record is opened and kept up as the event goes on.", "Deciding, and getting advice", "• The site packs under its customers' brands. Senior Site Management tells the brand owner the same day and decides with them whether it is a withdrawal or a recall. The brand owner leads the removal of product from its own customers and any notice to consumers; the site supplies the lot codes, quantities, dates and the reason, and makes no public statement about a customer's brand without that customer.", "• Advice comes from the FDA recall coordinator, the Florida Department of Agriculture and Consumer Services (FDACS) Division of Food Safety, legal counsel, a food safety consultant, and the supplier when its material is the cause. All are on the contact list, FRM-011 (SQF 2.6.3.1 ii).", "Telling people - the communication plan", "• Who is told, and when (SQF 2.6.3.1 iii):", "◦ Site personnel - the same day: what is on hold and what to do with it.", "◦ Customers (the brand owners) - by phone and then in writing the same day: the product, lot codes, quantities collected and dates, the reason, and what to do with the stock.", "◦ Consumers - through the brand owner, with the information the site supplies.", "◦ Authorities - FDA and FDACS as the law requires. Where there is a reasonable probability of serious harm to health, a Reportable Food Registry report is made to FDA within 24 hours.", "◦ Suppliers - when their material is the cause.", "• SQFI and the certification body are told in writing within 24 hours of identifying a food safety event that needs public notification - counted from the decision, recorded on FRM-012, that it needs one - or a product recall for any reason. SQFI is told at foodsafetycrisis@sqfi.com. SQFI, the certification body and the regulators are listed on FRM-011 as essential organizations (SQF 2.6.3.1 iv, 2.6.3.4).", "• Every notification is written on FRM-012: who was told, when, how and by whom.", "Getting product back", "• Product that comes back, or is held at a customer, is counted against what was dispatched on FRM-801. Returned product is held on FRM-702, kept apart from good stock, and dealt with under FSQM-018.", "• The lot is reconciled on FRM-012: quantity packed = collected by customers + still on site + retained on FRM-703 + disposed of. Anything unaccounted for is followed up with the brand owner until it is found or explained.", "Investigating and closing", "• The SQF Practitioner investigates the root cause and raises a CAPA on FRM-007 under FSQM-009. The investigation and the actions are recorded (SQF 2.6.3.3).", "• Senior Site Management closes the event on FRM-012 when the product is accounted for, the brand owner and the authorities have nothing outstanding, and the CAPA is raised.", "Testing the system - the mock recall", "• At least once a year the SQF Practitioner runs a mock recall and reviews this program, recorded on FRM-012 (SQF 2.6.3.2).", "• Each test goes both ways: a finished lot is traced back to every supplier lot and its receipt (one step back) and forward to every customer who collected it (one step forward); and an incoming material lot is traced forward to every finished lot it went into and on to those customers.", "• The choice changes each year: a material used across several products, and a lot that went to more than one customer where there is one. The site works a single shift, so the test covers different production days and products instead of different shifts.", "• The contact list, FRM-011, is checked in the same test: every number and address is confirmed current.", "• The test passes when every input is traced, the whole lot is accounted for, and it was done within 4 hours. A miss is raised as a CAPA on FRM-007, and the result goes to the management review.", "Records", "• FRM-012 records of mock recalls and of actual withdrawals and recalls, the CAPAs raised from them and the FRM-011 contact list are kept as SOP-2.2.3 requires (SQF 2.6.3.3)."], "definitions": "Withdrawal: removing product from sale or distribution for a reason that does not put anyone's health at risk, or before it reaches consumers.\nRecall: removing product that is or may be unsafe, including from consumers.\nBrand owner: the customer whose label the product carries.\nMock recall: a test of this program, run as if a lot had to be recalled.", "responsibility": "Senior Site Management - starts and manages a withdrawal or recall; tells the brand owner, the authorities, SQFI and the certification body; closes the event.\nSQF Practitioner - traces the affected lots, holds affected product, investigates the root cause, raises the CAPA; runs the annual mock recall and keeps FRM-011 current. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nProduction staff - stop, separate and tag affected product and materials when told.\nThe brand owner - leads the removal of product from its customers and any notice to consumers.", "form_references": "FRM-012 - Withdrawal, Recall and Mock Recall Record\nFRM-011 - Customer, Recall and Crisis Contact List\nFRM-520 - Production Lot Record\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-703 - Retention Sample Log\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "revision_history": "v2 - 2026-10-10 - FRM-011 is cited by its new title.\n\nFRM-011 was renamed \"Customer, Recall and Crisis Contact List\" (its v2). The list of linked forms is corrected to match. No part of the program changes.\n\nNew - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.3.1 and 2.6.3.2. The site had no withdrawal or recall procedure and had never run a mock recall.\n\nOWNER'S ANSWERS (2026-10-01): the site co-packs under customers' brands, so the brand owner leads the recall and the site supplies the trace; the mock recall target is 4 hours; no certification body has been chosen yet.\n\nTHE MOCK RECALL IS ALSO D-20's TRACE TEST: FSQM-021 says the annual trace test is part of this test, recorded on FRM-012.\n\nAT ISSUE: activate the 'traceability_test' row on the verification schedule (FSQM-017 Part 6) against FRM-012, yearly; issue FSQM-021 and FRM-520 first or with it.\n\nTO CONFIRM BEFORE ISSUE: (1) the customer agreements do make the brand owner responsible for consumer notices; (2) the certification body, once contracted, added to FRM-011; (3) legal counsel and a food safety consultant named on FRM-011; (4) the first mock recall run and recorded.\n\nRECALL WORKSPACE 2026-10-02 (owner): the trace is pulled from the records by the Team Portal - the Traceability page, and the workspace above each FRM-012 record with the 4-hour and 24-hour clocks and these steps ticked from the record. FRM-012 gained what it starts from, the hold reference, the decision, and a per-lot reconciliation table in place of the five quantity fields.\n\nISSUED 2026-10-07, with FSQM-024, FRM-011, FRM-012 and FRM-013; FSQM-021 and FRM-520 were issued the day before. What the draft listed to confirm (owner, 2026-10-07): (1) the customer agreements do make the brand owner responsible for telling consumers and the public, as written. (2) No certification body is contracted yet; it is added to FRM-011 when one is. (3) Legal counsel and a food safety consultant are entered on FRM-011 by Senior Site Management. (4) The first mock recall is due by 2026-12-31: the 'traceability and mock recall test' row of the verification schedule is now active, yearly, on FRM-012.\n\nv3 - 2026-10-29 - The 24-hour notice to SQFI and the certification body is counted from the decision, recorded on FRM-012, that the event needs public notification - the same point the recall record counts from. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.6.3.1, 2.6.3.2, 2.6.3.3 (Product Withdrawal and Recall), 2.6.3.4 (notifying SQFI and the certification body).\n\nFSQM-021 Product Identification and Traceability Program - the trace.\nFSQM-018 Non-Conforming Product and Equipment - held and returned product.\nFSQM-009 CAPA Program.\nFSQM-024 Crisis Management Plan.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.\nSOP-2.2.3 Document and Record Control Program - retention."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '004c7945-4e18-4dd3-9fa8-e27f6d8c2b05' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "The whole site and everything stored on it. Product that has already left the site is handled under FSQM-023.", "purpose": "This plan states how Adventure Bakery copes with an event that stops it making safe food - above all a hurricane - who decides, how affected product is found and checked, and how the site restarts safely.", "records": "• FRM-013 - one per annual review and test, and one per actual crisis\n• FRM-011 - the current contact list\n• FRM-702 holds and FRM-701 releases of affected product", "procedure": ["The dangers considered", "• Hurricane, tropical storm or other severe weather is the danger most likely to stop the site making safe food: the site is in central Florida (FSQM-028). It brings loss of power and refrigeration, water entering the building, a boil-water notice, and pests afterwards. It has its own part below.", "• Also considered, and handled by the general response below: loss of power or refrigeration on its own (the temperature alerts of SOP-401 raise it), fire, loss of the Team Portal or internet (records are kept on printed forms until it is back), loss of key staff (the backups in FSQM-004), and a pandemic.", "• Not credible for this site: ammonia leak (no ammonia refrigeration), tsunami, drought, warfare.", "Who decides, and the team", "• Senior Site Management is the senior manager responsible for decisions, oversight and starting the response (SQF 2.6.4.1 i).", "• The crisis management team is Senior Site Management and the SQF Practitioner, with the substitute SQF Practitioner standing in. The team is trained on this plan when it is issued and at every annual test; the test record, FRM-013, is the training record (SQF 2.6.4.1 ii).", "The general response - any crisis", "• People first. Once everyone is safe, Senior Site Management declares the crisis and calls the team.", "• Production stops, or does not start, until Senior Site Management says it can.", "• No response is allowed to put product at risk: nothing is made, packed or dispatched while the site has no power to the refrigerator or freezer, no safe water, a building that is not clean and sound, or pest activity. When work restarts, every control applies in full - the CCPs, the pre-operational check on FRM-903 and release on FRM-701 (SQF 2.6.4.1 iii).", "• Everything that was on site during the event - ingredients, packaging, work in progress and finished product - is treated as affected until it has been checked, and is put on hold on FRM-702 with its lot code (SQF 2.6.4.1 iv).", "• Before anything is released, the SQF Practitioner assesses each held lot under FSQM-018: its temperature record, any contact with water, the state of its packaging, and any sign of pests. Product is released only under FSQM-020 on FRM-701. Anything touched by flood or roof water, or chilled or frozen material with a gap in its temperature record that cannot be explained, is disposed of (SQF 2.6.4.1 v).", "• The crisis contact list is FRM-011: the team, the landlord, utilities, the insurer, customers, suppliers and the authorities. It is kept in the Team Portal, and a printed copy is kept off the site by the SQF Practitioner so that it can be reached when the site and the portal cannot. The printed copy is replaced each time the list is approved, and FRM-011 states where it is kept (SQF 2.6.4.1 vi).", "• Legal and expert advice - FDACS, FDA, legal counsel, the insurer and a food safety consultant - is listed on FRM-011 (SQF 2.6.4.1 vii).", "• Senior Site Management alone speaks for the site: to staff, to customers about delays and affected lots, to the authorities, to other organizations and to the media. Staff pass every enquiry on (SQF 2.6.4.1 viii).", "• If product that has already left the site may be affected, FSQM-023 starts.", "Hurricane or severe storm", "• Before the season - by 1 June each year: the plan is reviewed and tested and the contact list checked.", "• Watch - a storm is possible within about two days: Senior Site Management decides what production goes ahead. Whatever is started is finished and packed; no batter or unwrapped product is left. Ingredients and packaging are moved off the floor and away from doors. Customers are asked to collect finished product. Refrigerator and freezer temperatures are noted.", "• Warning or evacuation order: production stops, equipment is cleaned down and unplugged, and the site is closed. Nobody stays.", "• Afterwards, nobody returns until it is safe and allowed. Before any production:", "◦ The building is checked for roof leaks, water on the floor, broken glass (SOP-11.7.3) and pests (FSQM-031).", "◦ The temperature sensors run on batteries, but the hub that sends their readings needs mains power, so readings stop arriving during a power cut and the record has a gap. The gap runs from the last reading before the cut to the first after it. The refrigerator and freezer are treated as out of range for the whole of that gap, the product temperature is taken with the calibrated probe as soon as the site is entered, and the contents are dealt with under SOP-401.", "◦ The water is confirmed safe: no production under a boil-water notice (FSQM-033).", "◦ Anything touched by flood or roof water is put on hold and disposed of.", "◦ The site is cleaned and sanitized in full, and the pre-operational check on FRM-903 passed.", "• Senior Site Management then authorizes the restart, and the event is recorded on FRM-013.", "Review and test", "• At least once a year, before 1 June, the team walks through a storm scenario against this plan, checks the contact list, and records the review, who took part, the gaps found and the actions on FRM-013. Gaps are raised as CAPAs on FRM-007 (SQF 2.6.4.2).", "• The plan is also reviewed on FRM-013 after any real crisis.", "Records", "• FRM-013 reviews, tests and actual events, FRM-011 and the FRM-007 CAPAs are kept as SOP-2.2.3 requires (SQF 2.6.4.2)."], "definitions": "Crisis: an event that stops, or threatens, the site's ability to make and deliver safe food.\nCrisis management team: the people who run the response.\nWatch / warning: the National Weather Service's notices that a storm is possible (watch) or expected (warning) in the area.", "responsibility": "Senior Site Management - declares a crisis, makes the decisions, authorizes the restart, and speaks for the site to staff, customers, authorities and the media.\nSQF Practitioner - holds and assesses affected product and materials, runs the restart checks, keeps FRM-011 current, and prepares the annual test, which Senior Site Management leads. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - follow the team's instructions and pass every outside enquiry to Senior Site Management.", "form_references": "FRM-013 - Crisis Management Review and Test Record\nFRM-011 - Customer, Recall and Crisis Contact List\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-701 - Finished Product Release Record\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "revision_history": "v2 - 2026-10-10 - FRM-011 is cited by its new title.\n\nFRM-011 was renamed \"Customer, Recall and Crisis Contact List\" (its v2). The list of linked forms is corrected to match. No part of the program changes.\n\nNew - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.4.1 and 2.6.4.2. The site had no crisis management plan.\n\nOWNER'S DECISION (2026-10-01): the plan is written around the one danger that matters here, a hurricane or severe storm. The other dangers the Code lists were considered and are covered by the general response rather than by parts of their own.\n\nAT ISSUE: add a yearly 'crisis plan review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-013, due before 1 June.\n\nTO CONFIRM BEFORE ISSUE: (1) where the copy of the contact list is kept that can be reached without the site or the portal; (2) the insurer, landlord and utility contacts entered on FRM-011; (3) whether the temperature sensors keep recording through a power cut - if not, chilled and frozen stock after an outage has no record and is disposed of; (4) the first walk-through recorded on FRM-013.\n\nISSUED 2026-10-07, with FSQM-023 and the three records. What the draft listed to confirm (owner, 2026-10-07): (1) OFF-SITE COPY - there was none; the plan now says a printed copy is kept off the site by the SQF Practitioner and replaced each time the list is approved. (2) Insurer, landlord and utility contacts are entered on FRM-011 by Senior Site Management. (3) SENSORS - they run on batteries but the hub needs mains power, so a power cut leaves a gap in the record. The plan now says so: the units are treated as out of range for the whole gap and the product temperature is taken with the probe before anything is used. (4) The first review and test is due by 2027-05-31, before the storm season: a 'crisis management plan review and test' row is added to the verification schedule, yearly, on FRM-013.\n\nv3 - 2026-10-29 - Senior Site Management leads the annual test and the SQF Practitioner prepares it, as the verification schedule says. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.6.4.1, 2.6.4.2 (Crisis Management Planning).\n\nFSQM-023 Product Withdrawal and Recall Program.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-020 Product Release Program.\nSOP-401 Temperature-Controlled Storage; FSQM-033 Water Supply Program; FSQM-031 Pest Prevention Program; SOP-11.7.3.\nFSQM-028 Site and Local Environment Risk Assessment.\nFSQM-004 Organizational Structure and Responsibilities."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'a4dd00ae-f6ca-4214-a4f4-d19a98ddd660' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-702_Non-Conforming_Material_Hold_Tagging_Record.pdf", "path": "7717b881-1d6a-4bc7-9b54-41a8e3d1472c/files/FRM-702_Non-Conforming_Material_Hold_Tagging_Record.pdf"}, {"name": "FRM-702_Non-Conforming_Material_Hold_Tagging_Record.docx", "path": "7717b881-1d6a-4bc7-9b54-41a8e3d1472c/files/FRM-702_Non-Conforming_Material_Hold_Tagging_Record.docx"}], "form_schema": {"sections": [{"id": "section_1_initial_hold_identification", "title": "Section 1 — Initial Hold Identification", "fields": [{"id": "initial_hold_identification_info", "text": "To be filled out by the person placing the hold.", "type": "info", "label": "Instructions"}, {"id": "hold_tag_number", "type": "text", "label": "Hold Tag Number", "width": "half", "required": true, "showInList": true}, {"id": "date_time_placed_on_hold", "type": "datetime", "label": "Date / Time Placed on Hold", "width": "half", "showInList": true, "defaultToday": true}, {"id": "material_name_description", "type": "text", "label": "Material Name / Description", "width": "full", "required": true, "showInList": true}, {"id": "own_product", "type": "text", "label": "Product, if it is our own", "width": "half", "help": "For finished product or work in progress made here. Leave blank for a supplier's material."}, {"id": "own_lot_code", "type": "text", "label": "Our lot code", "width": "half", "showInList": true, "help": "The lot code printed on our product, e.g. 6302. Leave blank for a supplier's material."}, {"id": "supplier_name", "type": "text", "label": "Supplier Name", "width": "half", "required": false, "help": "For a supplier's material. Leave blank when the hold is of our own product."}, {"id": "po_number", "type": "text", "label": "P.O. Number", "width": "half"}, {"id": "supplier_lot_batch_number", "type": "text", "label": "Supplier Lot / Batch Number", "width": "full"}, {"id": "total_quantity_placed_on_hold", "type": "text", "label": "Total Quantity Placed on Hold", "width": "full"}, {"id": "exact_reason_for_hold", "type": "checkbox", "label": "Exact Reason for Hold (check all that apply)"}, {"id": "detailed_description_of_issue", "type": "textarea", "label": "Detailed Description of Issue", "width": "full"}, {"id": "material_status_tag", "type": "checkbox", "label": "Material Status", "width": "full"}, {"id": "storage_location_segregated", "type": "checkbox", "label": "Storage Location", "width": "full"}, {"id": "logged_tagged_by", "role": "filler", "type": "signature", "label": "Logged / Tagged By"}]}, {"id": "section_2_quality_review_supplier_coordination", "title": "Section 2 — Quality Review & Supplier Coordination", "fields": [{"id": "quality_review_info", "text": "To be filled out by the SQF Practitioner.", "type": "info", "label": "Instructions"}, {"id": "date_supplier_contacted", "type": "date", "label": "Date Supplier Contacted", "width": "full"}, {"id": "supplier_contact_person", "type": "text", "label": "Supplier Contact Person", "width": "full"}, {"id": "associated_scar_number", "type": "text", "label": "Associated SCAR Number", "width": "full"}, {"id": "associated_capa_number", "type": "text", "label": "Associated CAPA Number", "width": "full"}, {"id": "qa_evaluation_testing_notes", "type": "textarea", "label": "QA Evaluation & Testing Notes (internal spec verification / lab testing findings)", "width": "full"}]}, {"id": "section_3_final_disposition_release_authorizatio", "title": "Section 3 — Final Disposition & Release Authorization", "fields": [{"id": "final_disposition_info", "text": "To be filled out by the SQF Practitioner.", "type": "info", "label": "Instructions"}, {"id": "final_disposition_decision", "type": "select", "label": "Final Disposition Decision (check one)", "options": ["APPROVED FOR PRODUCTION RELEASE: Material is confirmed compliant or an acceptable deviation.", "RETURN TO SUPPLIER: Arranged under the approved supplier agreement terms.", "REWORK: Approved under overseen rework protocols.", "DESTRUCTION / DISPOSAL: Material cannot be salvaged; verified disposal completed."]}, {"id": "justification_for_final_disposition", "type": "textarea", "label": "Justification for Final Disposition", "width": "full"}, {"id": "verification_check", "type": "checkbox", "label": "Verification Check", "width": "full"}, {"id": "name_title", "type": "text", "label": "Name & Title", "width": "full"}, {"id": "authorized_quality_leader_signature", "role": "verifier", "type": "signature", "label": "Signature", "width": "half"}, {"id": "signature_date", "type": "date", "label": "Date", "width": "half"}]}], "settings": {}, "schemaVersion": 1}, "revision_history": "v2 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision.\n\nv3 - 2026-10-29 - A hold can name one of our own lots: 'Product, if it is our own' and 'Our lot code' added; Supplier Name is no longer required. Programs hold finished lots and CCP deviations on this record, which could only identify a supplier's material (readiness review)."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '7717b881-1d6a-4bc7-9b54-41a8e3d1472c' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "Applies to every non-conformance and every deviation from food safety requirements arising anywhere in the SQF System, whatever raised it: customer and consumer complaints, supplier non-conformances, non-conforming raw material, packaging, work-in-progress, finished product or equipment, non-compliance with a critical food safety limit, findings from internal and external audits and from regulatory inspections, findings from GMP and pre-operational inspections, environmental monitoring results, glass and brittle plastic breakage, and withdrawals and recalls including recall tests.\n\nThis program is the single route every one of those sources leads into. The record is FRM-007 (Corrective & Preventive Action Report) and the register is REP-007 (CAPA Log). The source form that raised the issue keeps its own detail; the CAPA number written back onto it is what ties the two together in both directions.\n\nWHAT THIS PROGRAM DOES NOT COVER. It governs the investigation and the action, not the fate of the product. Physical hold, tagging and disposition of non-conforming material are recorded on FRM-702 (Non-Conforming Material Hold & Tagging Record); the program governing that disposition is FSQM-018, which also authorises any rework. Executing a withdrawal or recall is FSQM-023 Product Withdrawal and Recall Program; this program covers the root cause investigation and the actions that follow one. The internal audit schedule itself is FSQM-038; this program covers what happens to the findings.", "purpose": "To document the responsibility and methods by which Adventure Bakery, LLC determines, implements and verifies corrective and preventive action — including the identification of the root cause and the resolution of non-compliance with critical food safety limits and deviations from food safety requirements — and to ensure that records of every investigation, root cause analysis, resolution, correction and preventive action are maintained.", "records": "Completed FRM-007 Corrective & Preventive Action Reports, with their investigation, root cause, actions, verification of effectiveness and closure, together with the evidence attached to each entry. Retained a minimum of two years, or the shelf life of the affected product plus twelve months, whichever is longer; permanently where the CAPA relates to a withdrawal or recall.\n\nThe REP-007 CAPA Log, held live in the Team Portal and exported at management review.\n\nThe monthly review of open and overdue CAPAs, recorded on FRM-009 Monthly SQF Update Record under \"Open corrective actions\".\n\nCAPA performance minuted at the annual management review on FRM-001.\n\nThe source records that raised each CAPA — FRM-002, FRM-205, FRM-702, FRM-908, FRM-913, FRM-903 — retained per their own retention periods, each carrying the CAPA number.", "procedure": ["PART 1 — WHAT RAISES A CORRECTIVE ACTION (SQF 2.5.3.1)", "> 2.5.3.1 names the sources a corrective and preventive action process shall serve: customer complaints, nonconformances raised at internal or external audits and inspections, non-conforming product and equipment, and withdrawals and recalls. This program serves all of them and the site's own additions, through one record.", "• **Customer and consumer complaints** — handled under SOP-2.1.3 and recorded on FRM-002. A complaint meeting Part 3 also opens a CAPA.", "• **Supplier non-conformances** — raised on FRM-205 (SCAR). The SCAR is the supplier's response; the CAPA is this site's own investigation of how the material reached the floor.", "• **Non-conforming raw material, packaging, work-in-progress or finished product** — held and tagged on FRM-702.", "• **Non-conforming equipment** — identified, tagged or segregated for repair or disposal, with the handling, corrective action and disposal recorded (11.1.7.9).", "• **Non-compliance with a critical food safety limit**, and any deviation at a CCP.", "• **Findings from internal audits**, and from external audits, certification body audits and regulatory inspections (2.5.4.1 iii, 2.5.4.4).", "• **Findings from GMP and pre-operational inspections** — the monthly site inspection on FRM-913 under FSQM-022, and the daily pre-operational check on FRM-903 (2.5.4.3 i).", "• **Environmental monitoring results** — a presumptive positive, an unsatisfactory result, or an adverse trend (2.4.8.3).", "• **Glass or brittle plastic breakage** — reported on FRM-908 under SOP-11.7.3.", "• **Withdrawals and recalls**, actual or from a recall test, and the root cause investigation into them (2.6.3.3).", "PART 2 — CORRECTION, CORRECTIVE ACTION AND PREVENTIVE ACTION ARE THREE DIFFERENT THINGS (SQF 2.5.3.1)", "• **Correction** is what is done to fix the thing observed — the pallet is removed, the surface is re-cleaned, the batch is held.", "• **Corrective action** is what is done so it does not happen again. It is written against the root cause of this non-conformance, not against the symptom.", "• **Preventive action** is what is done so the same cause cannot produce a non-conformance somewhere it has not yet occurred.", "> **The three are recorded separately on FRM-007.** A single “action taken” box conflates them, and that conflation is why findings repeat: the instance gets fixed and the cause does not.", "> A finding that recurs is telling you the correction was never followed by a corrective action. Repeats are flagged as repeats on FRM-007 and reviewed under Part 9.", "PART 3 — WHEN A CAPA IS OPENED (SQF 2.1.3.3, 2.5.3.1)", "> 2.1.3.3 requires corrective and preventive action to be implemented **based on the seriousness of the incident and the root cause analysis**. Escalation is therefore risk-based. Not every non-conformance becomes a CAPA; the ones below always do.", "> **A CAPA shall be opened for any of the following:**", "• Any non-conformance affecting product that has already been released, or that requires product to be held, reworked, downgraded or destroyed.", "• Any non-compliance with a critical food safety limit, or any deviation at a CCP.", "• Any complaint classified critical, and any complaint alleging illness, injury, foreign material or an undeclared allergen.", "• Any **repeat** — the same or substantially the same non-conformance within twelve months.", "• Any finding from an internal or external audit, a certification body audit, or a regulatory inspection.", "• Any finding at a GMP or pre-operational inspection that is not corrected on the spot, or that the person who found it cannot correct.", "• Any actual withdrawal or recall, and any withdrawal or recall test that misses its target or finds a gap (FSQM-023).", "• Any presumptive-positive or adverse trend in environmental monitoring.", "• Any glass or brittle plastic breakage where product or a food-contact surface was exposed.", "• Anything the SQF Practitioner judges to warrant one.", "> **A routine non-conformance corrected on the spot, and not caught by the list above, is recorded on the form that found it and does not open a CAPA.** That record still states what was seen and what was done — a same-day fix is still a finding, and an inspection record showing only unresolved items misrepresents how the site runs.", "> **When in doubt, open one.** An unnecessary CAPA costs an hour. A missed one costs a repeat finding, discovered by an auditor rather than by this site.", "PART 4 — RAISING A CAPA, AND CONTAINMENT FIRST (SQF 2.5.3.1)", "> Any employee may raise a non-conformance and shall report it immediately to a supervisor or to the SQF Practitioner.", "> **Containment comes before investigation.** Before anything is analysed: make the product safe. Hold and tag affected material on FRM-702, stop the process where it is still running, isolate the area or the equipment, and determine whether product already released is affected. **If released product may be affected, FSQM-023 is invoked immediately — it does not wait for the investigation to finish.**", "> The SQF Practitioner opens FRM-007 and assigns the number **CAPA-YYYY-NNN** — the calendar year and the next sequential number within that year, beginning at CAPA-2026-001. Numbers are never reused, and a CAPA that is later found to be unnecessary is closed with that reason rather than deleted.", "> **The number is written back onto the record that raised it** — the CAPA Ref field on FRM-002, the CAR Ref field on FRM-908, the CAPA No. column on FRM-913, and the equivalent reference on FRM-205 and FRM-702. That cross-reference is what lets an auditor trace in either direction: from a complaint to its investigation, or from the register back to what raised it.", "> What was contained, by whom and when is recorded on FRM-007 before the investigation begins.", "PART 5 — INVESTIGATION AND ROOT CAUSE (SQF 2.5.3.1, 2.1.3.2)", "> **Every CAPA has a documented root cause.** “Operator error” and “training issue” are not root causes. If an operator made an error, the question is why the process allowed that error to reach product undetected.", "> **The default method is Five Whys**, recorded on FRM-007 so the reasoning is visible and not just the conclusion. Where five whys is not adequate — a recurring failure, or one with several contributing causes — a cause-and-effect (fishbone) analysis is used and attached to the entry.", "> The investigation is carried out by a person **knowledgeable about the incident** (2.1.3.2) and, where practical, not the person whose work is under examination.", "> The investigation establishes: what happened; when it started; how much product and which lots are affected; why the control failed; and **why it was not detected sooner**. The last is a separate question from the first, and it is usually where the real corrective action lies — a control that failed and was caught is a different problem from one that failed and was not.", "PART 6 — CORRECTIVE AND PREVENTIVE ACTION (SQF 2.5.3.1, 2.5.4.4)", "> Actions are written against the root cause established in Part 5.", "> **Every action carries a named owner and a due date. An action without an owner and a date is not an action.** Both are recorded on FRM-007 when the action is agreed, not afterwards.", "> **Preventive action asks where else the same cause could bite** — another line, another product, another shift, another supplier, another piece of equipment with the same failure mode. Where the answer is nowhere, that is recorded as the answer.", "• Where an action changes a procedure, program, specification or form, the change is made under document control and the CAPA records the document and the revision it moved to.", "• Where an action requires training, the module is assigned in the Team Portal and the CAPA records the module and the people trained.", "• **Where a change arising from an internal audit affects the site's ability to deliver safe food, the applicable aspects of the SQF System are reviewed** (2.5.4.4, referring to 2.3.1.3), and that review is recorded on the CAPA.", "PART 7 — VERIFICATION OF EFFECTIVENESS (SQF 2.5.3.1)", "> 2.5.3.1 requires corrective and preventive actions to be determined, implemented **and verified**. Completing an action is not verification. **A CAPA is not closed because the work was done; it is closed because someone checked that it worked.**", "> **The verification method and date are set when the action is agreed, not after it is finished.** An action agreed without a verification plan will be closed on the day it is completed, which is the failure this Part exists to prevent.", "> The method is chosen to actually test the cause. Re-inspect the item at the next GMP inspection; review the next stated number of records or batches; re-test; re-audit the clause; watch the complaint category over the next quarter. **The verification date is at least one full cycle of whatever failed** — verifying a monthly check after one week proves nothing.", "> Verification is performed and signed by the SQF Practitioner or by a person independent of the action owner.", "> **If verification shows the action was not effective, the CAPA is not closed.** It is reopened: either the root cause was wrong or the action was insufficient, and the investigation resumes from Part 5. The failed verification stays on the record.", "PART 8 — CLOSURE (SQF 2.5.3.1)", "> A CAPA closes only when **all** of the following are true:", "• The correction is done and recorded.", "• The root cause is documented.", "• Every corrective and preventive action is complete.", "• Effectiveness has been verified and signed.", "• Any affected document, program or record has been updated.", "• The disposition of any affected product is resolved.", "> Closure is signed and dated by the SQF Practitioner on FRM-007.", "> **Open and overdue CAPAs are reviewed at least monthly** against REP-007, at the monthly SQF update, and **the review is recorded on FRM-009 Monthly SQF Update Record** under \"Open corrective actions\". An overdue action is followed up with its owner and a revised date is recorded with the reason on its FRM-007 — a due date that silently moves is not a controlled record.", "PART 9 — TRENDING AND MANAGEMENT REVIEW (SQF 2.1.2.1 iv, 2.1.3.2, 2.4.8.3)", "> **REP-007 (CAPA Log) is the register** — every CAPA with its source, severity, root cause, owner, due date and status, projected live from the FRM-007 entries. It is the answer to “show me your open corrective actions”.", "> The SQF Practitioner reviews the register at least monthly for overdue actions, repeats, and sources that keep recurring, in the same review, recorded on FRM-009. It covers the corrective actions opened and closed since the last monthly update - every one on record at the first - with the result of each effectiveness check, and every corrective action still open, whenever it was raised.", "> **CAPA performance is a standing item at management review** (2.1.2.1 iv) and is minuted on FRM-001: the number opened and closed in the period, the breakdown by source, what is overdue, and what has repeated.", "> **Adverse trends in complaint data are investigated and their root cause established by personnel knowledgeable about the incidents** (2.1.3.2), even where no single complaint met the Part 3 threshold. Where the trend itself is the non-conformance, a CAPA is opened against the trend.", "> Where environmental monitoring results or trends are unsatisfactory, preventive action is implemented through this program (2.4.8.3).", "PART 10 — RECORDS AND RETENTION (SQF 2.5.3.2, 2.5.4.4, 2.6.3.3)", "• **Records of all investigation, root cause analysis and resolution of non-conformities, their corrections, and the implementation of preventive actions are maintained** on FRM-007 and in the REP-007 register (2.5.3.2).", "• Records of internal audits and inspections, and of any corrective and preventive action taken as a result of them, are recorded through this program (2.5.4.4).", "• Records of withdrawal and recall tests, of the root cause investigation into any actual withdrawal or recall, and of the corrective and preventive actions applied, are recorded through this program (2.6.3.3).", "> Supporting evidence — photographs, laboratory reports, supplier correspondence, updated documents, training records — is attached to the FRM-007 entry, so the investigation and its evidence are one record rather than two.", "> **Retention: a minimum of two years, or the shelf life of the affected product plus twelve months, whichever is longer.** A CAPA relating to a withdrawal or recall is retained permanently."], "definitions": "Non-conformance — any departure from the SQF Food Safety Code, from this site's own documented programs, from a customer requirement or from a regulatory requirement, whether or not it was corrected on the spot.\n\nCorrection — what is done to fix the thing observed. Corrective action — what is done so it does not happen again. A repeat finding is usually a correction that was never followed by a corrective action.\n\nPreventive action — what is done so that the same cause cannot produce a non-conformance somewhere it has not yet occurred — another line, another product, another shift, another supplier.\n\nRoot cause — the reason the control failed, established by investigation rather than assumed. “Operator error” and “training issue” are not root causes; they are the point at which an investigation stopped.\n\nVerification of effectiveness — the check, made at a stated date after the action is complete, that the non-conformance has actually gone. Completing an action is not verification.\n\nRepeat — the same or substantially the same non-conformance recurring within twelve months, whether or not the earlier one was closed.\n\nCAPA — a Corrective and Preventive Action, opened under Part 3, numbered under Part 4 and recorded on FRM-007.", "responsibility": "SQF Practitioner — owns this program. Opens and numbers each CAPA, agrees the root cause, agrees every action with its owner and due date, sets the verification method and date, verifies effectiveness, and closes the CAPA. Reviews REP-007 at least monthly for overdue and repeat items, and reports CAPA performance to management review.\nAll staff — may raise a non-conformance, and shall report one immediately to a supervisor or to the SQF Practitioner. No employee is disadvantaged for raising one.\nAction owners — complete the action they accepted by the date they accepted, and tell the SQF Practitioner before the due date if they cannot.\nSupervisors — ensure containment happens immediately, and that a finding on their shift reaches the SQF Practitioner the same day.\nSenior management — reviews CAPA trends, overdue actions and repeat findings at management review, and provides the resources actions require.", "form_references": "FRM-007 — Corrective & Preventive Action (CAPA) Report — the record for every CAPA\nREP-007 — CAPA Log — the register, projected from FRM-007\nFRM-002 — Customer Complaint Report (raises a CAPA; carries the CAPA Ref)\nFRM-205 — Supplier Non-Conformance & Corrective Action Report (SCAR)\nFRM-702 — Non-Conforming Material Hold & Tagging Record (containment and disposition)\nFRM-908 — Glass Breakage Incident Report (carries the CAR Ref)\nFRM-913 — GMP / Food Safety Inspection Record (carries the CAPA No. column)\nFRM-903 — Daily Sanitation, Pre-Operation & Release Record\nFRM-001 — Management Review Record (CAPA trends)\nSOP-2.1.3 — Product Complaints\nSOP-11.7.3 — Glass & Brittle Plastic Control\nFSQM-022 — Food Safety Monitoring Program (the inspections that raise findings)\nFSQM-018 — Non-Conforming Product and Equipment (product disposition and rework)\nFRM-009 — Monthly SQF Update Record (the monthly review of open and overdue CAPAs)", "revision_history": "v2 — 2026-10-16 — Where the monthly CAPA review is recorded.\n\nPart 8 required open and overdue CAPAs to be reviewed at least monthly, and Part 9 the register to be reviewed for overdue actions, repeats and recurring sources, but neither said where the review is recorded. The verification schedule named FRM-007, the report of one corrective action, which cannot show a month's review, so its reminder could never be discharged. The review is done at the monthly SQF update and recorded on FRM-009 Monthly SQF Update Record under \"Open corrective actions\"; Parts 8 and 9 now say so, and Part 9 states what the review covers. FRM-009 is added to the forms referenced. Records corrected: CAPA performance is minuted at the ANNUAL management review on FRM-001 - the earlier text called it monthly - and the monthly review on FRM-009 is listed. No step of the program changes (owner's decision, 2026-10-16; FSQM-017 v16 changes the schedule line).\n\nNew — 2026-09-02 — Created under D-07 (CAPA Program + Investigation Form).\n\nWHY THIS DOCUMENT EXISTS. 2.5.3 Corrective and Preventative Action is a **Mandatory** element of the Code, and the site had no document against it. The gap assessment raised five Minor findings that this program and FRM-007 answer: 2.1.3.3 (no documented process for investigating and resolving complaints aligned to 2.5.3), 2.5.3.1 (no procedure stating the methods and responsibilities for corrective and preventive action), 2.5.3.2 (no records of investigation, root cause analysis and resolution), 2.5.4.4 (audit and inspection findings and their CAPAs not recorded per 2.5.3), and 2.6.3.3 (recall and withdrawal root cause investigations and their CAPAs not recorded).\n\nWHAT IT CLOSES, AND WHAT IT DOES NOT. The consultant's evidence against 2.5.4.4 reads that the site has not developed an Internal Audit Program, and against 2.6.3.3 that it has not developed a Product Recall and Withdrawal Program. **Those two programs are separate deliverables and this one does not claim them.** What this program closes is the records limb of each: that a finding from an audit or an inspection, and the root cause investigation into a withdrawal or recall, are raised, investigated, actioned, verified and retained through a documented CAPA process. When those two programs are written they will reference this one rather than restate it.\n\nIT ALSO CLOSES AN OPEN ITEM ON FSQM-022. That program was issued on 2026-09-01 stating: “the corrective-action half of this program has nowhere to live beyond FRM-913's own columns. D-07 (CAPA) is the object findings from any source should be raised into”. It now has one. FRM-913 gains a CAPA No. column in the same change, so an escalated inspection finding carries its number.\n\nTHE SITE WAS NOT STARTING FROM NOTHING, AND THIS PROGRAM SAYS SO. Four active fillable forms already capture root cause and corrective action for their own source: FRM-002 (complaints), FRM-205 (supplier SCAR), FRM-702 (non-conforming material hold) and FRM-908 (glass breakage, which has carried an unused CAR Ref field since it was written). What was missing was a governing procedure and a single register. Those forms are therefore kept and referenced, not replaced — a complaint needs the customer and the lot, a SCAR needs the supplier and the purchase order, and folding all of that into one universal form would have lost detail the sources need.\n\nESCALATION IS RISK-BASED BY DESIGN. Part 3 lists ten triggers that always open a CAPA and states that a routine on-the-spot correction stays on the form that found it. The alternative — a CAPA for every non-conformance — is simpler to audit but fills the register with trivia and hides the findings that matter, which for a site of this size would make the register useless within a quarter. 2.1.3.3 explicitly supports the risk-based reading: action is taken “based on the seriousness of the incident and the root cause analysis”.\n\nSETTLED AT ISSUE. The five points below were listed as open before activation. The program was reviewed and ISSUED AS WRITTEN by GJM on 2026-09-02, which adopts the position each of items 1 to 4 states in the body — the retention period in Part 10, closure by the SQF Practitioner in Part 8, the ten triggers in Part 3, and the verification arrangement in Part 7. Those are now the site's stated position and not open questions; they are kept here because the reasoning behind each is what an auditor will ask about. Item 5 is a dependency on another document and remains genuinely open.\n1. RETENTION PERIOD. Part 10 and Records state a minimum of two years, or shelf life plus twelve months where that is longer, and permanent retention for a recall-related CAPA. This is written to sit alongside FRM-908's two-year retention and FRM-903's twelve months. Confirm it, or state the period the site intends.\n2. WHO MAY CLOSE A CAPA. Part 8 gives closure to the SQF Practitioner alone. On a team this size that is a single point of failure, and a CAPA the practitioner owns as an action is one the practitioner then verifies and closes. Name a second person authorised to close, or confirm the single-signature arrangement deliberately.\n3. THE TEN TRIGGERS IN PART 3. They were written to catch what an auditor will look for, not from watching this floor. Read them against how the site actually runs: too low and the register fills with trivia, too high and a repeat finding reaches the auditor before it reaches the register.\n4. VERIFICATION INDEPENDENCE. Part 7 asks for verification by the SQF Practitioner or someone independent of the action owner. Where the practitioner is the action owner there is no independent verifier on site. Confirm the fallback — a second employee, or an accepted and stated limitation.\n5. FSQM-018 IS A DRAFT. The Scope points at it for the disposition of non-conforming product and says so plainly rather than implying an approved document exists. FRM-702 is active and is the operative record today. FSQM-018 should be issued or withdrawn.\n\nDELIVERED WITH THIS PROGRAM: FRM-007 (the report), REP-007 (the register), a CAPA Ref field on FRM-002 with the matching column on REP-003 — a gap the codebase had already documented and left open — and a CAPA No. column on each of FRM-913's eight Module 11 grids.\n\nEvery form, procedure and program named in this document was checked against the live register on 2026-09-02 and exists. FSQM-018 is named explicitly as a draft. Nothing here repeats the FSQM-022 mistake of requiring a record that was never built.\n\nISSUED 2026-09-02, approved GJM. Status active, revision New. FRM-007 (the record) and REP-007 (the register) are activated in the SAME TRANSACTION, so this program is never active without the form it requires or the register it reports from — the same sequencing that kept the site from ever being without a personnel hygiene document when FSQM-012 superseded SOP-11.3.\n\nSTILL OPEN AFTER ISSUE: FSQM-018 Non-Conforming Product and Equipment remains an unapproved draft. The Scope names it as a draft rather than implying otherwise. FRM-702 is active and is the operative record for holding and tagging non-conforming material until FSQM-018 is issued or withdrawn.\n\nv3 - 2026-10-29 - Stale references corrected: FSQM-018 is issued (it was described as a draft); rework is authorised under FSQM-018, not the draft FSQM-019; the recall procedure and the internal audit program are named as FSQM-023 and FSQM-038. Approved GJM.\n\nv4 - 2026-10-29 - A withdrawal or recall test raises a CAPA when it misses its target or finds a gap, as FSQM-023 says; an actual withdrawal or recall always does. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — 2.5.3 Corrective and Preventative Action (Mandatory). 2.5.3.1: the responsibility and methods outlining how corrective and preventative actions are determined, implemented and verified, including the identification of the root cause and resolution of non-compliance of critical food safety limits and deviations from food safety requirements, shall be documented and implemented. 2.5.3.2: records of all investigation, root cause analysis and resolution of non-conformities, their corrections, and the implementation of preventative actions shall be maintained.\n\n2.1.3.3 — corrective and preventative action implemented based on the seriousness of the incident and the root cause analysis as outlined in 2.5.3; records of customer complaints, their investigation and resolution maintained.\n\n2.5.4.4 — records of internal audits and inspections and any corrective and preventative actions taken as a result shall be recorded as per 2.5.3, and changes affecting the site's ability to deliver safe food require a review of applicable aspects of the SQF System.\n\n2.6.3.3 — records of withdrawal and recall tests, root cause investigations into actual withdrawals and recalls, and corrective and preventative actions applied.\n\nAlso served: 2.1.2.1 (iv) management review of corrective and preventative actions and trends; 2.1.3.2 adverse complaint trends investigated and root cause established; 2.4.8.3 preventative action on unsatisfactory environmental results; 2.5.4.1 (iii) and 2.5.4.3 (i) corrective and preventative action on internal audit and inspection findings; 11.1.7.9 records of the handling, corrective action and disposal of non-conforming equipment."}$jx$::jsonb,
       revision = 'v4', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '6d069d17-c19f-4ef2-bbfd-1a9968046d81' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-903-Daily_Sanitation.docx", "path": "96b9eed2-3665-4857-a81c-b839d4f83f9d/files/FRM-903-Daily_Sanitation.docx"}, {"name": "FRM-903-Daily_Sanitation.pdf", "path": "96b9eed2-3665-4857-a81c-b839d4f83f9d/files/FRM-903-Daily_Sanitation.pdf"}], "form_schema": {"sections": [{"id": "details", "title": "Day / Shift", "fields": [{"id": "inspection_date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "area_line", "type": "select", "label": "Production area / line", "width": "third", "options": ["Production floor", "Dry storage room", "Other"], "showInList": true, "defaultValue": "Production floor"}, {"id": "shift", "type": "select", "label": "Shift", "width": "third", "options": ["1st Shift", "2nd Shift", "3rd Shift"], "showInList": true, "defaultValue": "1st Shift"}, {"id": "product_run", "help": "What is being produced today (leave blank if no production)", "type": "text", "label": "Product / batch run", "width": "half", "lotLink": {"fromField": "inspection_date"}, "suggestFrom": {"form": "FRM-501", "field": "product_name", "drafts": true}}]}, {"id": "preop_surfaces", "title": "1. Pre-Operation Cleanliness Check", "fields": [{"id": "surface_check", "rows": {"mode": "fixed", "labels": ["Tables", "Mixers", "Bowls", "Utensils", "Pans", "Racks", "Ovens", "Scales", "Depositors", "Floors", "Handwash stations (clean, stocked, draining)", "Restrooms / sanitary facilities", "Break room / lockers (staff amenities)"], "addLabel": "Add item", "deletable": true, "labelHeader": "Item / Surface"}, "type": "grid", "label": "Surface & equipment check", "columns": [{"id": "visibly_clean", "type": "pass_fail", "label": "Visibly clean", "width": 1, "required": true}, {"id": "sanitized", "type": "pass_fail", "label": "Sanitized", "width": 1, "required": true}, {"id": "corrective", "type": "text", "label": "Corrective action / comments", "width": 3}]}], "description": "Before production starts, following cleaning and sanitation, confirm each item is visibly clean and sanitized (SQF 11.2.5.7). The clause covers the processing areas and product contact surfaces AND the staff amenities and sanitary facilities, so all of them are listed here. Mark Pass, Fail, or N/A — N/A is the right answer for \"Sanitized\" on an area that is cleaned but not sanitized, such as a locker room. Note any corrective action taken before start-up. Add or remove items as the line changes."}, {"id": "equipment_ssop", "title": "2. Production Equipment — Cleaned & Sanitized per SSOP", "fields": [{"id": "equipment_status", "rows": {"mode": "fixed", "labels": ["Hobart V-1401 Mixer — SOP-901 / FRM-909", "Kook-E-King Depositor — SOP-902 / FRM-910", "Beldos 275 Depositor — SOP-903 / FRM-911", "Smipack S560NA Shrink Wrapper — SOP-601", "Groen TDB Kettle — SOP-904 / FRM-912", "Molds — SOP-906 (recorded here)"], "addLabel": "Add equipment", "deletable": true, "labelHeader": "Equipment"}, "type": "grid", "label": "Equipment", "columns": [{"id": "status", "type": "select", "label": "Status", "width": 2, "options": ["Clean & sanitized", "Between-use care (scrape, wipe, re-grease)", "Not used today"], "required": true}, {"id": "notes", "type": "text", "label": "Notes", "width": 3}]}], "description": "For each machine used in today's production, confirm it was verified clean and sanitized per its SSOP and recorded on its own cleaning log, or mark \"Not used today\". Items without a separate log — the molds — are recorded here. Molds are scraped, wiped and re-greased between uses and washed weekly under SOP-906, so record which of those happened. Add or remove equipment as the line changes."}, {"id": "sanitizer", "title": "3. Detergent & Sanitizer Verification", "fields": [{"id": "detergent_used", "type": "text", "label": "Detergent used", "width": "third", "defaultValue": "Dawn Professional"}, {"id": "detergent_concentration", "help": "Per the manufacturer's instructions - Dawn Professional is 1-2 oz per 10 gallons of water", "type": "text", "label": "Detergent concentration", "width": "third", "required": true, "defaultValue": "1-2 oz per 10 gallons"}, {"id": "detergent_within_target", "type": "pass_fail", "label": "Detergent within target?", "width": "third", "required": true}, {"id": "detergent_test_method", "help": "How the dose was measured - pump strokes, measuring cup or proportioner. The Dawn Professional pump delivers 1 oz per full stroke.", "type": "text", "label": "Detergent test method", "width": "full", "defaultValue": "Measured dose per sink fill"}, {"id": "sanitizer_used", "type": "text", "label": "Sanitizer used", "width": "third", "defaultValue": "Noble Sani-512"}, {"id": "concentration_ppm", "type": "text", "label": "Concentration (PPM)", "width": "third", "required": true, "defaultValue": "200 ppm"}, {"id": "sanitizer_verified", "type": "pass_fail", "label": "Within target?", "width": "third", "required": true}, {"id": "test_method", "type": "text", "label": "Test method (e.g. test strip)", "width": "full", "defaultValue": "Test strip"}, {"id": "footbath_note", "text": "Foot baths — use the HIGH-RANGE quat strip. The baths run Sani-512 at 1:160, roughly three times the 1:512 food-contact strength. The 0-400 ppm strips used on equipment saturate at this concentration and will read high on a bath that has failed. Change the solution when the strip reads below target, when the bath is visibly soiled, or when it has been diluted by water carried in or by washdown.", "type": "info", "label": "Foot bath check"}, {"id": "footbath_check", "rows": {"mode": "fixed", "labels": ["Production entrance (from office / break room / reception)", "Walkthrough — production to inventory & packaging"], "addLabel": "Add foot bath", "deletable": true, "labelHeader": "Foot bath"}, "type": "grid", "label": "Foot baths — Sani-512 at 1:160", "columns": [{"id": "reading", "type": "text", "label": "Reading (ppm)", "width": 1}, {"id": "within_target", "type": "pass_fail", "label": "At strength?", "width": 1, "required": true}, {"id": "condition", "type": "pass_fail", "label": "Clean & not diluted?", "width": 1, "required": true}, {"id": "action", "type": "text", "label": "Action (none / recharged / changed)", "width": 2}]}], "description": "Confirm and record detergent and sanitizer concentration before use (SQF 11.2.5.3). Site chemicals: Dawn Professional detergent at 1-2 oz per 10 gallons of water; Noble Sani-512 sanitizer at the food-contact dilution of 1:512 (1 fl oz per 4 gallons, about 200 ppm quat)."}, {"id": "glass", "title": "4. Glass & Brittle Plastic Check", "fields": [{"id": "glass_check", "rows": {"mode": "fixed", "labels": ["Processing Room", "Processing Room", "Processing Room"], "addLabel": "Add item", "deletable": true, "labelHeader": "Location", "defaultValues": [{"item": "Pan scrubber dials"}, {"item": "Oven controls and door glass"}, {"item": "MIG thermometers"}]}, "type": "grid", "label": "Glass dial covers & MIG thermometers", "columns": [{"id": "item", "type": "text", "label": "Item", "width": 2}, {"id": "undamaged", "type": "pass_fail", "label": "Undamaged", "width": 1, "required": true}, {"id": "comments", "type": "text", "label": "Condition / comments", "width": 2}, {"id": "action", "type": "text", "label": "Action taken", "width": 2}]}], "description": "At the start of the shift, confirm glass instrument dial covers and MIG thermometers are undamaged (SQF 11.7.3.4). Mark Pass (undamaged), Fail (damaged/broken), or N/A. Any Fail requires a Glass Breakage Incident Report (FRM-908) and follows SOP-11.7.3. Items are drawn from the Glass & Brittle Plastic Register (FRM-907)."}, {"id": "operational_gmp", "title": "5. Operational GMP Check", "fields": [{"id": "gmp_check", "rows": {"mode": "fixed", "labels": ["Hair/beard nets worn; no exposed jewelry", "Clean outer garments; no eating/drinking/gum in production", "Handwash stations stocked (soap, towels, sanitizer)", "Hands washed on entry and as required", "Allergen controls / segregation followed", "Waste and floor debris controlled", "No condensation or drip over exposed product", "Pest control devices in place and intact", "Doors/screens to outside kept closed"], "addLabel": "Add check", "deletable": true, "labelHeader": "Check"}, "type": "grid", "label": "Operational GMP check", "columns": [{"id": "result", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "comments", "type": "text", "label": "Corrective action / comments", "width": 3}]}], "description": "During production, confirm operational GMPs are being followed. Mark Pass, Fail, or N/A; note corrective action for any Fail (absorbs the former FRM-904 Daily Operation Check)."}, {"id": "release", "title": "6. Corrective Actions & Release", "fields": [{"id": "all_corrected", "type": "pass_fail", "label": "All corrective actions completed before start-up", "width": "half", "required": true}, {"id": "single_person", "type": "checkbox", "label": "Single-person operation: only one qualified person was on site, and the same person did the sanitation and this inspection (FSQM-004)", "width": "full"}, {"id": "released_by", "role": "filler", "type": "signature", "label": "SQF Practitioner (qualified inspector)", "width": "half", "required": true, "statement": "I inspected the area and equipment before start of production, verified the sanitizer concentration, and confirm the area is clean and released for production (or corrective action was completed as noted)."}, {"id": "supervisor", "role": "verifier", "type": "signature", "label": "Production Supervisor", "width": "half", "statement": "I confirm the pre-operation inspection was completed and the area is released for production."}], "description": "Production shall not begin until all non-conformances are corrected and the area is verified clean (SOP-11.2.12). A record of pre-operational hygiene inspection is maintained for a minimum of two years (SOP-2.2.3; SQF 11.2.5.9)."}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "{inspection_date} — Daily Sanitation & Pre-Op Record"}, "schemaVersion": 1}, "revision_history": "v6 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision.\n\nv6 - 2026-10-29 - A tick for single-person operation in the release section, which FSQM-004 requires to be recorded. Optional field; no revision change."}$jx$::jsonb,
       revision = 'v6'
 where id = '96b9eed2-3665-4857-a81c-b839d4f83f9d' and status = 'active' and revision = 'v6';
update public.sop_documents set content = $jx${"form_schema": {"sections": [{"id": "identification", "title": "1. Batch identification", "fields": [{"id": "release_info", "text": "One record per batch or lot released. Nothing is made available for collection until this record is complete and signed — not afterwards. The customer's carrier will not wait, so this is done before it arrives.\n\nOnly the SQF Practitioner may release finished product (FSQM-020 Part 2). If any check below fails, do not release: place the batch on Hold under FSQM-018 and record it on FRM-702.", "type": "info", "label": "Before you start"}, {"id": "lot_code", "help": "Exactly as coded on the pack. Choose it from the list, or type it.", "type": "text", "label": "Lot / batch code", "width": "half", "required": true, "showInList": true}, {"id": "product_name", "help": "Comes with the lot. Choose or type it if the lot is not on the list.", "type": "text", "label": "Product", "width": "half", "required": true, "showInList": true}, {"id": "batch_sheet_ref", "type": "text", "label": "Batch sheet reference", "width": "third"}, {"id": "date_produced", "type": "date", "label": "Date produced", "width": "third"}, {"id": "line_or_area", "type": "text", "label": "Line / area", "width": "third"}, {"id": "quantity_released", "help": "Cases, units or weight — state which.", "type": "text", "label": "Quantity released", "width": "third"}, {"id": "customer", "type": "text", "label": "Customer", "width": "third", "showInList": true, "suggestFrom": {"form": "FRM-011", "grid": "contacts", "field": "_label", "where": {"column": "group", "equals": "Customer (brand owner)"}, "drafts": true, "current": true}}]}, {"id": "release_checks", "title": "2. Release checks", "fields": [{"id": "checks_info", "text": "Every row must be answered. N/A is a legitimate answer where a check genuinely does not apply to this product — say why in the note. A single Fail means the batch is not released.\n\nA note that arrives already filled in is what the site's records show for this lot. It is evidence, not the answer: read it, check what it says, then choose the result yourself.", "type": "info", "label": "How to use this table"}, {"id": "checks", "rows": {"mode": "fixed", "labels": ["Batch sheet complete and signed, CCP records reviewed\nFormula, process steps and process controls followed as specified, and the lot's CCP 1 baking and CCP 2 sealing records (FRM-507, FRM-606) within their limits and verified.", "Line pre-operation and sanitation release recorded\nOn FRM-903, for the line that produced this batch.", "No hold applies\nNeither the batch nor any ingredient in it is on Hold under FSQM-018, and no hold tag applies.", "Label is the approved label\nVerified against REP-602. Allergen statement and any Gluten Free claim correct for what was actually run.", "Pack, seal and package integrity correct\nAs specified for this product and customer.", "Date and lot code present, legible and correct", "Appearance and sensory standard met\nA unit taken from the batch and examined.", "Quantity and pack configuration match the customer's agreed specification", "Net weight\nThree finished packs weighed. With the empty packaging taken off, their average is at or above the net weight on the label. Weights recorded below."], "labelHeader": "Check"}, "type": "grid", "label": "Checks required before release (FSQM-020 Part 4)", "columns": [{"id": "result", "type": "pass_fail", "label": "Result", "width": 1, "required": true}, {"id": "note", "type": "text", "label": "Note / evidence", "width": 3}]}, {"id": "net_weight_declared", "help": "As printed on the pack, with its unit", "type": "text", "label": "Net weight on the label", "width": "third"}, {"id": "packaging_tare", "help": "The empty pouch, baking cup and box together, in the same unit", "type": "number", "label": "Empty packaging weight", "width": "third"}, {"id": "net_weight_unit", "type": "select", "label": "Unit weighed in", "width": "third", "options": ["oz", "g", "lb"]}, {"id": "pack_weight_1", "help": "The whole finished pack, as weighed", "type": "number", "label": "Pack 1 weight", "width": "third"}, {"id": "pack_weight_2", "type": "number", "label": "Pack 2 weight", "width": "third"}, {"id": "pack_weight_3", "type": "number", "label": "Pack 3 weight", "width": "third"}]}, {"id": "label_verification", "title": "3. Label verification", "fields": [{"id": "label_info", "text": "The check in Section 2 confirms the label applied is the approved one. This section confirms the approved one is lawful — required before a product's first release and again at every label change (FSQM-020 Part 6). For a repeat run of an unchanged label, record the approved label reference and tick the confirmation.", "type": "info", "label": "What this section is for"}, {"id": "approved_label_ref", "help": "As held on REP-602 Approved Label Register.", "type": "text", "label": "Approved label reference", "width": "half"}, {"id": "label_version", "type": "text", "label": "Label version / revision", "width": "half"}, {"id": "first_release_or_change", "type": "checkbox", "label": "This is a first release or the label has changed since the last release", "width": "full"}, {"id": "legal_compliance_confirmed", "type": "checkbox", "label": "Label compliance with applicable food law confirmed (country of manufacture, and of sale where known)", "width": "full"}]}, {"id": "decision", "title": "5. Release decision", "fields": [{"id": "decision", "type": "select", "label": "Decision", "width": "half", "options": ["RELEASED — may be shipped, collected or transferred", "NOT RELEASED — placed on Hold under FSQM-018"], "required": true, "showInList": true}, {"id": "hold_tag_number", "help": "The tag raised on FRM-702. Leave blank when the batch is released.", "type": "text", "label": "Hold tag number, if not released", "width": "half"}, {"id": "release_notes", "help": "Anything a reader would need to understand this decision later. Required in substance where a check was answered N/A or Fail.", "rows": 3, "type": "textarea", "label": "Notes", "width": "full"}, {"id": "released_by", "type": "signature", "label": "Released by (SQF Practitioner)", "width": "half", "required": true, "statement": "I have completed the checks above and release this batch on the evidence recorded here."}, {"id": "release_date", "type": "date", "label": "Date of release", "width": "half", "required": true, "showInList": true, "defaultToday": true}]}], "settings": {"releaseAssist": true, "attachmentsEnabled": true, "allowMultipleDrafts": true, "instanceTitleTemplate": "Release {lot_code} — {product_name}"}, "schemaVersion": 1}, "revision_history": "v3 - 2026-10-29 - The batch check row also asks that the lot's CCP records (FRM-507, FRM-606) are within limits and verified. Label only; no revision change."}$jx$::jsonb,
       revision = 'v3'
 where id = 'a8388458-9e6c-4184-b41e-57fb4547c522' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"statement": "Management Responsibilities and Quality Objectives\n\nScope\n\nThis policy applies to all personnel at Adventure Bakery, including full-time, part-time, and temporary staff. Responsibilities cover food safety, product quality, and compliance with regulatory and customer requirements.\n\nResponsibility and Authority\n\nAdventure Bakery’s management ensures that all personnel are trained and competent to perform their assigned duties related to food safety and quality. Senior Site Management has overall responsibility for maintaining and improving the Food Safety and Quality Management System (FSQMS) in compliance with the SQF Code.\n\nResponsibilities include:\n\n• Maintaining the SQF System and ensuring it meets applicable requirements.\n\n• Allocating necessary resources for food safety and quality.\n\n• Conducting management reviews and approving system updates.\n\n• Communicating food safety objectives to all staff.\n\n• Ensuring that external contractors or visitors comply with GMP and food safety policies.\n\nSQF Practitioner\n\nThe primary and substitute SQF Practitioner are designated by Senior Site Management, and the designation is recorded on FRM-005 SQF Practitioner Designation Record. They are two different people, because the substitute covers the primary's absence; either may also hold other positions (FSQM-004).\n\nEach of them shall:\n\n• Be employed by the site.\n\n• Hold a position of responsibility related to the management of the site's SQF System.\n\n• Have completed a HACCP training course.\n\n• Be competent to implement and maintain HACCP-based food safety plans.\n\n• Understand the SQF Food Safety Code: Food Manufacturing and what is needed to implement and maintain an SQF System for the site's scope of certification.\n\nFRM-005 records how each holder meets each of these. The HACCP training certificate and the evidence of competency are kept on FRM-952 under SOP-2.9. A person who does not meet all five is not designated, with one exception: the HACCP training course may be recorded on FRM-005 as Pending when it is booked, with its date. The designation then stands until that date, and if the course has not been completed by then a new FRM-005 entry is made. A new FRM-005 entry is also made whenever either holder changes.\n\nThe SQF Practitioner is responsible for implementing, maintaining, and verifying the effectiveness of the Food Safety Plan and the overall SQF System. This includes:\n\n• Coordinating food safety training.\n\n• Managing corrective and preventive actions.\n\n• Verifying internal audit findings and follow-up.\n\n• Ensuring communication with certification bodies and regulatory agencies.\n\nBlackout Periods\n\nSenior Site Management designates the site's blackout periods on FRM-006 Blackout Period Declaration: the defined date ranges when an unannounced re-certification audit should not take place because the site is closed or out of season for legitimate business reasons, each with its business reason. One entry covers one period. The site's normal operating days are recorded on the same entry as its operating pattern, and are not claimed as blackout dates.\n\nThe submitted declaration is sent to the certification body at least one month before the sixty-day window for the unannounced re-certification audit opens. Until a certification body is appointed, it is kept on file. A new declaration is made before the period in force ends, and whenever the operating pattern changes.\n\nFood Safety and Quality Objectives\n\nAdventure Bakery strives to:\n\n1. Produce safe and high-quality products that meet SQF and customer standards.\n\n2. Achieve zero major non-conformances in internal and external audits.\n\n3. Ensure 100% of staff complete GMP and food safety training annually.\n\n4. Maintain 100% traceability for all raw materials and finished products.\n\n5. Keep customer complaints low: no more than one complaint a year that raises a food safety concern, and no more than one quality complaint a month.\n\n6. Continuously review and improve systems to enhance product quality and process control.\n\nQuality objectives are reviewed annually during management review meetings, and progress is documented for continuous improvement.\n\nCommunication\n\nAdventure Bakery maintains clear communication channels for food safety and quality matters. Internal communication occurs through daily production meetings, periodic management reviews, and corrective action reports. External communication includes updates to suppliers, co-packers, and customers regarding product safety, specifications, and compliance.", "revision_history": "v5 - 2026-10-29 - A booked HACCP course may be recorded as Pending on FRM-005 at designation, with its date; FRM-005 already allowed this, and without it no SQF Practitioner could be designated until the course is done. Approved GJM."}$jx$::jsonb,
       revision = 'v5', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '5e2f96fc-35f9-4842-877b-582ebe0c2896' and status = 'active' and revision = 'v4';
update public.sop_documents set content = $jx${"form_schema": {"sections": [{"id": "material", "title": "1. The material", "fields": [{"id": "how_this_works", "text": "ONE ENTRY IS ONE MATERIAL AS APPROVED: a named product from a named manufacturer. The Entries list is the specification library - material, category, manufacturer and whether it is current - and each entry carries the manufacturer's specification sheet and allergen statement as attachments.\n\nWHAT 2.3.2.2 ASKS FOR. Specifications for all raw materials and packaging that impact finished product safety - ingredients, additives, processing aids, packaging and hazardous chemicals - documented and kept current.\n\nWHY THE BRAND IS PART OF IT. SOP-2.3.4 approves a material bought through a distributor as a named product from a named manufacturer. The approved brand recorded here is what the Brand / Manufacturer column on FRM-301 is checked against at every delivery. A different brand is a new material: record it under Approved alternates only once its allergens have been checked.\n\nA DISCONTINUED MATERIAL STAYS ON THE REGISTER, marked Discontinued. Deleting it would leave no record of what was specified when it was in use.", "type": "info", "label": "How this register works"}, {"id": "material_name", "help": "The site's own name for it. Filled from the pack's product name by the scan in Section 2 - change it if the site calls it something else.", "type": "text", "label": "Material", "width": "half", "required": true, "scanFact": "product_name", "showInList": true}, {"id": "category", "type": "select", "label": "Category", "width": "half", "options": ["Ingredient", "Additive / flavouring", "Processing aid", "Packaging - food contact", "Packaging - not food contact", "Hazardous chemical"], "required": true, "showInList": true}, {"id": "status", "type": "select", "label": "Status", "width": "third", "options": ["Current", "Under review", "Discontinued"], "required": true, "showInList": true}, {"id": "used_in", "help": "The products or process steps that use it.", "type": "textarea", "label": "Where it is used"}]}, {"id": "source", "title": "2. Approved source", "fields": [{"id": "source_info", "text": "Use Scan pack on this section and photograph the label. One photo fills the whole entry where the pack shows it: the manufacturer, product name, item code and net weight here; the storage instruction in Section 3; and in Section 4 the ingredient statement, the Contains statement and any may-contain statement, word for word. The photo is kept on the entry as the evidence for what was transcribed.\n\nIF THE PANEL IS ON ANOTHER SIDE, scan that side too - each scan fills what it can read.\n\nCHECK EVERY VALUE BEFORE SAVING, the allergens above all. The allergen boxes are ticked only from the printed Contains statement, never guessed from the ingredient list; if no Contains statement was readable they are left blank and the scan says so.\n\nBOUGHT FROM is the distributor or supplier, chosen from the approved supplier register - it is not on the pack, so the scan never fills it.", "type": "info", "label": "Photograph the pack to fill this entry"}, {"id": "manufacturer", "type": "text", "label": "Manufacturer / brand", "width": "half", "required": true, "scanFact": "brand", "showInList": true}, {"id": "manufacturer_product", "type": "text", "label": "Manufacturer's product name", "width": "half", "required": true, "scanFact": "product_name"}, {"id": "item_code", "type": "text", "label": "Manufacturer / distributor item code", "width": "third", "scanFact": "item_code"}, {"id": "pack_size", "type": "text", "label": "Net weight / pack size", "width": "third", "scanFact": "net_weight"}, {"id": "bought_from", "help": "Only suppliers with a submitted FRM-202 approval (Approved or Conditionally Approved) can be chosen - the same list as REP-201. A material the customer supplies (the rum, the pecans) is 'Supplied by the customer' (SOP-2.3.4).", "type": "select", "label": "Bought from", "width": "third", "options": ["Supplied by the customer"], "multiple": true, "required": true, "scanFact": "none", "optionsFrom": {"form": "FRM-202", "field": "supplier_name", "filters": [{"op": "in", "field": "supplier_status", "values": ["APPROVED – meets all documentation or recognized-distributor requirements.", "CONDITIONALLY APPROVED – lacks one or more documents but poses low food-safety risk (recognized distributor)."]}], "emptyText": "No supplier has a submitted approval yet. Approve the supplier on FRM-202 and submit it; it then appears here."}}, {"id": "alternates", "help": "Other brands accepted for this material. A brand is added here only after its allergen declaration has been checked against Section 4; if its allergens differ, it needs the SQF Practitioner's review first, because the allergen statement on finished product may have to change.", "rows": {"mode": "dynamic", "addLabel": "Add alternate brand"}, "type": "grid", "label": "Approved alternates", "columns": [{"id": "brand", "type": "text", "label": "Manufacturer / brand", "width": 3}, {"id": "product", "type": "text", "label": "Product name / code", "width": 3}, {"id": "allergens_same", "type": "select", "label": "Allergens vs approved", "width": 2, "options": ["Same", "Different - reviewed"]}, {"id": "approved_on", "type": "date", "label": "Approved on", "width": 2}, {"id": "notes", "type": "text", "label": "Notes", "width": 3}]}], "scanMode": "specification", "scanLabel": true, "scanScope": "form"}, {"id": "specification", "title": "3. Specification (2.3.2.2)", "fields": [{"id": "spec_info", "text": "ATTACH THE MANUFACTURER'S SPECIFICATION SHEET to this entry - the Attachments section is at the bottom. For a branded product bought through a distributor this document takes the place of a certificate of analysis for each lot, which a distributor does not issue.\n\nWhere no specification exists - common for commodity items - record what the site specifies instead in the description below, and say so. A blank is not a specification.", "type": "info", "label": "What the specification is"}, {"id": "spec_on_file", "type": "select", "label": "Manufacturer specification", "width": "half", "options": ["Attached to this entry", "Held elsewhere - named below", "Requested, not yet received", "None issued - site specification below"], "required": true}, {"id": "spec_location", "type": "text", "label": "Where it is held", "width": "half"}, {"id": "spec_issue_date", "help": "The date printed on the manufacturer's sheet, so a newer one can be recognised.", "type": "date", "label": "Specification issue date", "width": "third"}, {"id": "description", "help": "What the material is and what it must be - form, colour, key limits the manufacturer states.", "type": "textarea", "label": "Description and key characteristics", "required": true}, {"id": "storage", "type": "select", "label": "Storage", "width": "third", "options": ["Ambient", "Chilled - at or below 40°F", "Frozen"], "required": true, "scanFact": "storage"}, {"id": "shelf_life", "help": "Unopened, as stated by the manufacturer; and once opened, where it differs.", "type": "text", "label": "Shelf life", "width": "third"}]}, {"id": "allergens", "title": "4. Allergens", "fields": [{"id": "allergen_info", "text": "Record what the manufacturer declares - the ingredient statement and the Contains statement word for word, and any \"may contain\" or \"made in a facility with\" statement. These are what an alternate brand is checked against at receipt, and they feed the allergen statement on finished product.\n\nFROM A SCAN: the Contains boxes are ticked by matching the words of the printed Contains statement shown below them, so each ticked box can be traced to the pack. A scan never ticks \"None of the major allergens\" - only a person can decide there are none.\n\nCHECK THE TRANSCRIPTION. The first scans of a Pillsbury bag each replaced \"NONFAT MILK, XANTHAN GUM, GUAR GUM\" with a different ingredient that is not on the bag. A scan warns when the Contains statement declares an allergen the ingredient statement no longer names, and unticks the confirmation below whenever it fills either statement, so an entry cannot be submitted until a person has compared them with the pack.", "type": "info", "label": "Read the declaration, not the product name"}, {"id": "ingredient_statement", "help": "Word for word from the pack or specification sheet.", "type": "textarea", "label": "Ingredient statement (as printed)", "scanFact": "ingredients"}, {"id": "contains_statement", "help": "e.g. \"CONTAINS WHEAT, MILK, SOY AND EGG INGREDIENTS.\" Blank where the pack carries none.", "type": "text", "label": "Contains statement (as printed)", "scanFact": "contains_statement"}, {"id": "declarations_checked", "help": "Read them side by side, ingredient by ingredient. A scan transcribes them and can misread or drop part of a dense panel.", "type": "checkbox", "label": "I have checked the ingredient statement and the Contains statement above word for word against the pack or the specification sheet", "required": true, "clearOnScanOf": ["ingredient_statement", "contains_statement"]}, {"id": "allergens_contains", "type": "select", "label": "Contains", "options": ["Milk", "Egg", "Wheat", "Soy", "Peanut", "Tree nuts", "Sesame", "Fish", "Crustacean shellfish", "None of the major allergens", "Not applicable - not a food ingredient"], "multiple": true, "required": true, "scanFact": "allergens"}, {"id": "may_contain", "help": "Word for word from the pack or statement. Write \"none\" where there is none.", "type": "textarea", "label": "May contain / precautionary statement", "scanFact": "may_contain"}, {"id": "allergen_statement", "type": "select", "label": "Allergen statement", "width": "half", "options": ["Attached to this entry", "On the specification sheet", "Taken from the pack label - photo attached", "Not applicable - not a food ingredient"], "required": true}]}, {"id": "review", "title": "5. Review and approval", "fields": [{"id": "review_info", "text": "2.3.2.2 requires specifications to be KEPT CURRENT. Review each entry at least annually and whenever the manufacturer issues a new sheet, changes the product, or a different brand is bought. Ask the supplier to tell the site of any change in composition - allergens especially - and record that it was asked.", "type": "info", "label": "Keeping it current"}, {"id": "change_notice", "type": "select", "label": "Supplier asked to notify changes in composition", "width": "half", "options": ["Yes - recorded", "Not yet"]}, {"id": "next_review", "type": "date", "label": "Next review of this entry", "width": "half", "required": true}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Reviewed and approved by the SQF Practitioner", "required": true, "statement": "This specification is current, the manufacturer and product named are the ones approved for this material, and the allergens recorded match the manufacturer's declaration."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{material_name} — {manufacturer}"}, "schemaVersion": 1}, "revision_history": "v3 - 2026-10-29 - 'Supplied by the customer' can be chosen under Bought from, for the rum and pecans (SOP-2.3.4). No revision change."}$jx$::jsonb,
       revision = 'v3'
 where id = '32e5fb32-ec41-4474-b6dc-3a8d377b8779' and status = 'active' and revision = 'v3';
update public.sop_documents set content = $jx${"scope": "This procedure applies to all suppliers that provide ingredients, packaging, or cleaning chemicals used in the bakery’s production process. It also governs the emergency receipt of material from a supplier that is not approved, and material supplied by any site under the same ownership as Adventure Bakery.", "purpose": "The purpose of this procedure is to establish how Adventure Bakery selects, approves, and monitors suppliers of ingredients, packaging, and cleaning materials that may affect product safety or quality.", "records": "• FRM-202 Supplier Approval & Evaluation Record\n• FRM-203 Vendor & Supplier Questionnaire (completed and signed)\n• REP-201 Approved Supplier Register\n• FRM-301 entries for emergency receipts — Approved Supplier column N, the authorisation and the inspection result in Comments\n• Purchase Orders with supplier-verification checkbox\nReview Frequency\nSupplier list and documentation reviewed annually by SQF Practitioner.", "procedure": ["Suppliers are evaluated based on the type of product or service provided and their ability to meet food-safety and quality requirements.", "The following documentation may be requested when available:", "• Certificate of Analysis (COA)", "• Safety Data Sheet (SDS)", "• Allergen Statement", "• Certificate of Origin or Letter of Guarantee", "• Kosher, Organic, Gluten-Free, or Non-GMO documentation (if applicable)", "• Third-party audit certificate (GFSI, HACCP, or similar) or completed Vendor Questionnaire", "Suppliers that cannot provide full documentation (for example, Sysco or Restaurant Depot) may still be conditionally approved if they are recognized distributors supplying commercially regulated food products.", "The SQF Practitioner will review supplier performance and documentation at least annually to confirm approval status.", "Supplier Status", "• Approved: Supplier meets all documentation or recognized-distributor requirements.", "• Conditionally Approved: Supplier lacks one or more documents but poses low food-safety risk.", "• Rejected: Supplier cannot demonstrate food-safety compliance or product traceability.", "> **Contract service providers are not approved through the steps above.** Pest control, chemical supply, laundry, waste haulage, calibration, external laboratory and sanitation providers supply a service rather than a material, and a certificate of analysis or an allergen statement asks them nothing. The description of their services, the training and licences their personnel must hold, and their contract are recorded on **FRM-206 Contract Services Register**, one entry per provider, as SQF 2.3.2.8 requires.", "Adventure Bakery uses no contract manufacturer, and arranges no third-party storage or distribution.", "> Every product the site supplies is made on its own site: no other business makes or packs any part of it. Released product goes straight to the customer, collected at the dock or shipped to them; storage or distribution the customer arranges after that is the customer's. SQF 2.3.3 Contract Manufacturers is therefore not applicable. If either changes, the change is assessed under FSQM-007 and this procedure is revised before the first such product is made, stored or shipped.", "> Materials the customer supplies - the rum and the pecans for the rum cake - are not bought, so the customer is not approved as a supplier on FRM-202. Each is entered on FRM-207 as 'Supplied by the customer', with the customer's specification or the declaration on its pack, and each delivery is received and inspected on FRM-301 like any other (FSQM-026).", "Material from a supplier that is not approved is received only in an emergency, and only once the SQF Practitioner has authorised it.", "• An emergency is a supply failure that would otherwise stop or delay production: an approved supplier out of stock or unable to deliver in time, or a delivery rejected at receipt with no approved replacement available. Price, convenience and product trials are not emergencies — a supplier wanted for those is approved on FRM-202 first.", "• The SQF Practitioner authorises the receipt before the material is accepted, for the quantity needed to cover the shortfall and no more.", "• The delivery is recorded on FRM-301 like any other, with the Approved Supplier & COA/LOG/COC column marked N and the Comments recording EMERGENCY – NON-APPROVED SUPPLIER, who authorised it, and the result of the receiving inspection.", "• The receiving inspection is completed and recorded before the material is used: identity against the purchase order, the label and its allergen declaration against the material specification, packaging integrity, lot code and best-by date, and temperature where the material is chilled. Any COA, LOG or COC the supplier can provide is attached to the FRM-301 entry.", "• Material that fails, or whose inspection has not been recorded, is not used. Failed material is segregated, tagged HOLD – DO NOT USE on FRM-702 and dispositioned under FSQM-018.", "• An emergency receipt does not approve the supplier. If the supplier is to be used again it is approved on FRM-202 before the next order; otherwise it is not used again.", "Material from another site under the same ownership as Adventure Bakery is treated exactly as material from any other supplier.", "> Adventure Bakery has no other site today: no site under common ownership supplies it with ingredients, packaging or part-made product. The rule is stated so that shared ownership is never taken as a substitute for approval if one ever does. Such a site is approved on FRM-202, its materials are held to the specifications SOP-2.3.2 requires, and each delivery is received and inspected on FRM-301 like any other (SQF 2.3.4.5).", "A material bought through a recognised distributor is approved as a named product from a named manufacturer, not as whatever the distributor supplies under that description.", "• The brand on the pack is checked at receipt against the brand approved for that material, and recorded in FRM-301's Brand / Manufacturer column. A different brand — a distributor's substitution, or a different brand picked up in store — is a new material, even from an approved distributor.", "• Before a substituted brand is used, its allergen declaration, including any \"may contain\" statement, is checked against the specification of the material it replaces. If the allergens are the same, it is used and the substitution noted in the FRM-301 Comments. If they differ, it is not used until the SQF Practitioner has reviewed the change, because the allergen statement on finished product may have to change with it.", "• A distributor does not provide a certificate of analysis for each lot. For each material bought through one, the manufacturer's product specification or allergen statement is kept on file instead, as SOP-2.3.2 requires, and the per-delivery checks on FRM-301 stand in for the per-lot certificate."], "definitions": "", "not_applicable": [{"clause": "2.3.3", "reason": "Every product is made on site and released product goes straight to the customer: the site uses no contract manufacturer and arranges no third-party storage or distribution."}], "responsibility": "The SQF Practitioner is responsible for evaluating, approving, and maintaining supplier records. The SQF Practitioner will ensure that all materials are purchased from approved suppliers whenever possible.\nThe SQF Practitioner authorises any receipt of material from a supplier that is not approved. Production staff receiving it complete and record the receiving inspection on FRM-301 before the material is used.", "form_references": "FRM-202 - Supplier Approval & Evaluation Record (approving a supplier, including one first used in an emergency)\nFRM-203 - Vendor & Supplier Questionnaire\nREP-201 - Approved Supplier Register (a report projected from FRM-202 entries; nothing is filled in on it)\nFRM-301 - Incoming Material Receiving & Inspection Log (every delivery, including emergency receipts)\nFRM-702 - Non-Conforming Material Hold & Tagging Record (material that fails its receiving inspection)\nFSQM-018 - Non-Conforming Product and Equipment (disposition of held material)\nFRM-206 - Contract Services Register (contract service providers, SQF 2.3.2.8)", "revision_history": "v2 — 2026-09-16 — Cross-reference to FRM-206 Contract Services Register added, under D-10.\n\nFRM-206 was issued with nothing referring to it. The register stands on its own and appears in the Document Register, but somebody following this procedure had no way to reach it, and a register nobody is sent to is a register nobody fills.\n\nTHE LINE IS A CROSS-REFERENCE, NOT A SCOPE EXTENSION. This procedure's scope is suppliers of ingredients, packaging and cleaning chemicals, and its approval steps are a COA, an SDS, an allergen statement and a third-party certificate. A pest control company has none of those and should not be run through the list. The new paragraph therefore says what a contract service provider is not — approved through these steps — before saying where it is recorded.\n\nThe SQF reference on this document is unchanged for the same reason: 2.3.2.8 is satisfied by FRM-206, not by this procedure, and pointing at a register is not a claim to cover the clause behind it.\n\nv3 — 2026-09-16 — Form references pinned to document numbers.\n\nv2 added a numbered reference to FRM-206 and left two unnumbered ones beside it. One was merely vague — \"FRM Vendor & Supplier Questionnaire\" is FRM-203. The other was wrong in a way that matters: \"FRM Approved Supplier Register\" is REP-201, and it is not a form at all. It is a report projected from FRM-202's entries, with no entries of its own, so calling it an FRM tells somebody to go and fill in a document that cannot be filled in.\n\nThe same two documents appeared again in the records list under different loose names — \"Vendor Questionnaire\" and \"Approved Supplier List\", the latter not being any document's title. Both are pinned, because fixing one field and leaving the other would reproduce the inconsistency one line down.\n\nFRM-202, FRM-204 and FRM-205 are deliberately not added. They exist and they belong to this subject, but the body of this procedure does not mention them — it predates them — and a reference list should describe the procedure it sits on rather than the filing cabinet around it. Closing that gap is a rewrite, and it belongs to D-11.\n\nv4 — 2026-09-18 — Emergency receipt from a non-approved supplier, and material from sites under common ownership, under D-11.\n\nTwo Minor findings against this procedure, and one rule for distributors. 2.3.4.4: receipt from a non-approved supplier is acceptable only in an emergency and only after a receiving inspection is conducted and recorded — there was no route for it, so the procedure's \"whenever possible\" left the exception undefined. 2.3.4.5: material from another site under the same corporate ownership is held to the same specification, approval and receiving requirements as any supplier — there was no provision.\n\nTHE EMERGENCY ROUTE IS RECORDED ON FRM-301, NOT A NEW FORM. The receiving log already carries an Approved Supplier column and a Comments / Hold Status column, and its own instructions already say an unlisted supplier needs authorisation before acceptance. What was missing was the procedure those instructions point at: what counts as an emergency, who authorises, what the inspection covers, and that the material is not used until the inspection is recorded. A separate emergency-receipt form would be a second account of one delivery.\n\nAN EMERGENCY RECEIPT DOES NOT APPROVE THE SUPPLIER. Without that line the route becomes a side door: one emergency order and a supplier is in use indefinitely without ever having been approved.\n\nTHERE IS NO OTHER SITE. The owner confirmed on 2026-09-18 that no site under common ownership supplies Adventure Bakery. The rule is stated anyway, because 2.3.4.5 asks for the provision rather than the circumstance, and because shared ownership is exactly the relationship in which approval gets skipped.\n\nDISTRIBUTORS: A BRAND SUBSTITUTION IS A NEW MATERIAL. Most material arrives through Sysco and Restaurant Depot, already conditionally approvable here as recognised distributors. What a distributor's approval does not cover is the brand: when an item is out of stock the distributor substitutes, or a different brand is picked up in store, and a different cake mix can carry a different allergen profile. The new step makes the brand part of what is approved, checks it at every receipt, and holds a substitution with different allergens until it has been reviewed. It also states what stands in for a per-lot certificate of analysis, which a distributor does not provide.\n\nFRM-202, FRM-301, FRM-702 and FSQM-018 are added to the form references now that the body names them. The existing body, the Supplier Status list and the contract services paragraph are unchanged.\n\nv5 - 2026-10-17 - States that the site uses no contract manufacturer and arranges no third-party storage or distribution (owner, 2026-10-17), so SQF 2.3.3 Contract Manufacturers is not applicable, and what happens if that changes. The FSMS Index records the determination against this procedure. Nothing else in this procedure is changed by this revision.\n\nv6 - 2026-10-29 - Role names and record retention aligned to FSQM-004 and SOP-2.2.3, after the readiness review of 2026-10-29. Approved GJM.\n\nv7 - 2026-10-29 - Materials the customer supplies (rum, pecans) are entered on FRM-207 as 'Supplied by the customer' and received on FRM-301; the customer is not approved as a supplier. Approved GJM.", "governing_reference": ""}$jx$::jsonb,
       revision = 'v7', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'eb46f728-e635-45a7-9d46-7a9b501ed429' and status = 'active' and revision = 'v6';

update public.sop_documents set status = 'archived' where id = '25a39c19-663f-4fca-8502-d405c0fb2a7e' and status = 'draft';

do $verify$
begin
  if (select revision from public.sop_documents where sop_number = 'FRM-702') <> 'v3' then raise exception 'FRM-702 not revised.'; end if;
  if exists (select 1 from public.sop_documents where status = 'active' and (content - 'revision_history')::text like '%FSQM-019%') then
    raise exception 'an active document still cites FSQM-019.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number = 'FSQM-019' and status <> 'archived') then raise exception 'FSQM-019 not archived.'; end if;
end $verify$;

commit;
